def test_the_render_gate_requires_a_declared_conversations_host(browser, serve):
    """A conversation declaration whose module omits its host fails visibly.

    The shipped module first proves the gate accepts the real page. The bug-back then
    removes only its conversationBox placement from the vendored module; a fresh browser
    context prevents the clean load's module cache from answering for the changed file."""
    url = serve(ASK_PAGE)
    assert interact.render_version(browser, url) == []

    module = serve.page_dir / "widgets" / "lf-options.js"
    source = module.read_text()
    placement = """        this.#conversation = conversationBox(this, "Say something");
        if (this.#conversation) this.append(this.#conversation);
"""
    assert source.count(placement) == 1
    module.write_text(source.replace(placement, ""))

    failures = interact.render_version(browser, url)
    assert (
        "[light] <lf-options id='jobs'> declares x-conversation but rendered 0 "
        "matching hosts; its module must place exactly one conversationBox"
    ) in failures


def test_the_render_gate_catches_a_lying_verbatim_and_an_undeclared_shadow_root(
    browser, serve, tmp_path, monkeypatch
):
    """Bug-back for two module contracts the gate enforces: an entry that says
    x-verbatim while the module renders other words in the body's stead (quotes
    would strand on words the screen no longer shows), and a module attaching a
    shadow root its entry doesn't declare (the passage walk crosses only the
    declared ones, so an undeclared root's words anchor astray)."""
    monkeypatch.chdir(tmp_path)
    result = CliRunner().invoke(
        interact.cli, ["customize", "widget", "lf-callout", "--upgrade"]
    )
    assert result.exit_code == 0, result.output
    module = tmp_path / ".leaf" / "widgets" / "lf-callout.js"
    module.write_text(
        'import { once } from "/leaf.js";\n'
        "customElements.define(\n"
        '  "lf-callout",\n'
        "  class extends HTMLElement {\n"
        "    connectedCallback() {\n"
        "      if (!once(this)) return;\n"
        '      this.textContent = "Entirely different words.";\n'
        '      const stage = document.createElement("div");\n'
        "      this.append(stage);\n"
        '      stage.attachShadow({ mode: "open" }).textContent = "shadow words";\n'
        "    }\n"
        "  },\n"
        ");\n"
    )

    failures = interact.render_version(browser, serve(CUSTOM_WIDGET_PAGE))

    assert any("x-verbatim" in f for f in failures), failures
    assert any("shadow roots the registry doesn't declare" in f for f in failures), (
        failures
    )


def test_the_render_gate_catches_a_declared_word_that_never_reached_the_page(
    browser, serve, tmp_path, monkeypatch
):
    """Bug-back for the other thing a declaration promises: that the words arrive. Both
    word passes stop at a shadow boundary on purpose — which widgets the page holds is
    the document's question — so an element a module stages into its own tree keeps its
    declarations and gets neither pass, and the failure is silence: no error, no missing
    box, nothing a reading of the drawn page can tell from an attribute with nothing to
    say. Here a project widget stages an <lf-event>, whose entry declares both keys, and
    the gate is asked for each.

    A staged element rather than a module that wipes its own body after the passes have
    run, which is the same failure by the reachable-today route: that one is a race with
    the next poll for the painted half, and a bug-back that has to win a race is a
    bug-back that reports the machine."""
    monkeypatch.chdir(tmp_path)
    result = CliRunner().invoke(
        interact.cli, ["customize", "widget", "lf-callout", "--upgrade"]
    )
    assert result.exit_code == 0, result.output
    registry_path = tmp_path / ".leaf" / "registry.json"
    entries = json.loads(registry_path.read_text())
    # The scaffold's x-verbatim claim is about a body this module no longer shows, and
    # the gate says so on its own; declaring the root keeps this test's finding the
    # only one about the tree.
    entries["lf-callout"].pop("x-verbatim")
    entries["lf-callout"]["x-shadow"] = True
    registry_path.write_text(json.dumps(entries, indent=2))
    module = tmp_path / ".leaf" / "widgets" / "lf-callout.js"
    module.write_text(
        'import { once, shadowStage } from "/leaf.js";\n'
        "customElements.define(\n"
        '  "lf-callout",\n'
        "  class extends HTMLElement {\n"
        "    connectedCallback() {\n"
        "      if (!once(this)) return;\n"
        '      const staged = document.createElement("lf-event");\n'
        '      staged.id = "staged-event";\n'
        '      staged.setAttribute("at", "09:00");\n'
        '      staged.setAttribute("kind", "failure");\n'
        '      staged.textContent = "The feeder stopped.";\n'
        "      shadowStage(this, [staged]);\n"
        "    }\n"
        "  },\n"
        ");\n"
    )

    failures = interact.render_version(browser, serve(CUSTOM_WIDGET_PAGE))

    assert any('never says "09:00"' in f for f in failures), failures
    assert any('paints kind="failure" and says nothing' in f for f in failures), (
        failures
    )


# The host case of the same failure: the declarations are on the element that stages the
# tree, so both passes find it — it is in the document — and write into a light DOM the
# shadow root hides. The markup then holds every word the entry promised and the reader
# gets none of them, which is why the gate reads the rendered page rather than the markup.
SHADOW_HOST_PAGE = CUSTOM_WIDGET_PAGE.replace(
    '<lf-callout id="custom-note">',
    '<lf-callout id="custom-note" label="Escalated" urgent>',
)


def test_the_render_gate_catches_a_shadow_host_whose_own_words_never_render(
    browser, serve, tmp_path, monkeypatch
):
    """Bug-back for the half a reading of the markup cannot see. `textContent` returns a
    hidden light-DOM span and `querySelector` finds it, so a check written against the
    markup passes on a page whose reader is handed neither word. Asking `says()` for the
    words and a box for the clipped one is what tells the two apart — the layer's own
    reading enters a declared root in the host's stead, and a span rendered nowhere has
    no rects."""
    monkeypatch.chdir(tmp_path)
    result = CliRunner().invoke(
        interact.cli, ["customize", "widget", "lf-callout", "--upgrade"]
    )
    assert result.exit_code == 0, result.output
    registry_path = tmp_path / ".leaf" / "registry.json"
    entries = json.loads(registry_path.read_text())
    entry = entries["lf-callout"]
    entry.pop("x-verbatim")  # the module shows a tree of its own, not the body
    entry["x-shadow"] = True
    entry["properties"]["label"] = {"type": "string"}
    entry["properties"]["urgent"] = {"type": "boolean"}
    entry["x-says"] = {"label": "before"}
    entry["x-paints"] = ["urgent"]
    registry_path.write_text(json.dumps(entries, indent=2))
    module = tmp_path / ".leaf" / "widgets" / "lf-callout.js"
    module.write_text(
        'import { once, shadowStage } from "/leaf.js";\n'
        "customElements.define(\n"
        '  "lf-callout",\n'
        "  class extends HTMLElement {\n"
        "    connectedCallback() {\n"
        "      if (!once(this)) return;\n"
        '      const stage = document.createElement("p");\n'
        '      stage.textContent = "The feeder stopped overnight.";\n'
        "      shadowStage(this, [stage]);\n"
        "    }\n"
        "  },\n"
        ");\n"
    )

    failures = interact.render_version(browser, serve(SHADOW_HOST_PAGE))

    assert any('never says "Escalated"' in f for f in failures), failures
    assert any('paints urgent="" and says nothing' in f for f in failures), failures


@pytest.mark.parametrize("example", EXAMPLES, ids=lambda p: p.stem)
def test_example_renders(browser, serve, example):
    """Every shipped example loads clean and lays out, in both color schemes: no
    fail-soft error box, no console error, every visible widget occupies real
    space, no sideways scroll, no words on screen a selection can't reach. A
    widget that upgrades into a 1x1 box, or a heading painted by a pseudo-element,
    is the shape of failure a static lint cannot see. The invariants live in
    interact.render_version — the pass `version check --render` runs on agent-authored
    pages — so this sweep also proves the gate a user's page goes through."""
    assert interact.render_version(browser, serve(example)) == []


def test_every_idiom_in_the_catalog_stands_in_an_example(browser):
    """The sweep above is the corpus's own gate, and an idiom no example holds never
    reaches it: the shape passes every test it has, because it has none. It is the
    floor test_every_widget_in_the_vocabulary_stands_in_an_example is for widgets, and
    the reason it is here rather than beside that one is that an idiom is declared as a
    selector, which only a layout engine can answer.

    Asked of the authored markup and not of the upgraded page, so an idiom stands
    because an example writes it rather than because a widget's own rendering happens
    to match — a `<table>` a module builds demonstrates nothing about the shape an
    author is being pointed at. The gallery is left out for the same reason it is left
    out of the widget floor: generated from the others, it can only repeat them.

    Every key is put to the engine, so a key that is not a selector fails here too.
    `pre > code.language-*` was one for as long as nothing asked — readable, matching
    nothing, and the only member of the catalog with no way to be checked."""
    registry = interact.incoming_registry([interact.ASSETS, interact.BUNDLED])
    idioms = [key for key in registry["$idioms"] if key != "description"]
    assert idioms, "no idioms read — an empty catalog demonstrates itself"
    page = browser.new_page()
    held, invalid = set(), set()
    for example in EXAMPLES:
        if example.stem == "gallery":
            continue
        page.set_content(example.read_text(), wait_until="domcontentloaded")
        answer = page.evaluate(
            """(selectors) => {
                const held = [], bad = [];
                for (const s of selectors) {
                    try { if (document.querySelector(s)) held.push(s); }
                    catch { bad.push(s); }
                }
                return {held, bad};
            }""",
            idioms,
        )
        held |= set(answer["held"])
        invalid |= set(answer["bad"])
    page.close()

    assert not invalid, f"not selectors, so nothing can ask for them: {sorted(invalid)}"
    assert not set(idioms) - held, (
        f"no example holds {', '.join(sorted(set(idioms) - held))}"
        " — see examples/CLAUDE.md"
    )


# Every cell one unbreakable token, so no amount of wrapping gets this table
# inside the column and the third of the theme's three cases is the one on trial.
WIDE_TABLE_PAGE = leaf_page(
    "wide",
    """
<h1 id="t">Sessions</h1>
<p id="p">One row, and more of it than the measure holds.</p>
<table id="sessions">
<thead><tr>{heads}</tr></thead>
<tbody><tr>{cells}</tr></tbody>
</table>
""",
).format(
    heads="".join(f"<th>heading_number_{i}</th>" for i in range(8)),
    cells="".join(f"<td>value_number_{i}</td>" for i in range(8)),
)

# A block wider than the column and narrower than the window: 70% of 1200px is
# 840px against a 720px column, so it stands 120px out in the margin with
# the body not scrolling by a pixel. In vw rather than px because the static lint
# counts pixels and would have caught it before a browser ever saw it.
SPILLING_PAGE = LONG_PAGE.replace(
    "</main>", "<div id='too-wide' style='width: 70vw'>Wide.</div>\n</main>"
)


def test_a_table_too_wide_to_wrap_scrolls_inside_the_column(browser, serve):
    """The theme's answer for a table with more in it than the column holds. Its
    columns hold what is in them, so it takes the measure only when it needs to
    and wraps its cells past that; when even wrapping can't fit it scrolls inside
    itself — like pre, like lf-board — rather than out into the margin
    where a suggestion's controls hang. `width: 100%` had no third case: the
    table spilled, and at this viewport the window is wide enough that nothing
    scrolled to say so."""
    url = serve(WIDE_TABLE_PAGE)
    page, errors = open_page(browser, url)
    measured = page.locator("#sessions").evaluate(
        """(t) => {
        const main = t.closest('main'), pad = parseFloat(getComputedStyle(main).paddingRight);
        const column = main.getBoundingClientRect().right - pad;
        return { past: Math.round(t.getBoundingClientRect().right - column),
                 scrolls: Math.round(t.scrollWidth - t.clientWidth),
                 sideways: document.body.scrollWidth - document.body.clientWidth };
    }"""
    )
    # Where the width went, then that there was width to go anywhere: a table
    # narrow enough to fit satisfies the first of these while proving nothing,
    # and it is the second that says this one was never such a table.
    assert measured["past"] <= 0
    assert measured["scrolls"] > 0, "this table fits, so it proves nothing"
    assert measured["sideways"] == 0
    assert errors == []
    page.close()
    assert interact.render_version(browser, url) == []


def test_the_render_gate_reports_content_set_past_the_column(browser, serve):
    """The reading neither of the gate's older ones can give. The window is the
    wider of the two boxes — 1200px against a 720px column — so content can stand
    out in the margin with the body still not scrolling sideways, and the
    static lint reads pinned pixels, which a vw width is not. The failure names
    the element and how far out it is, because "something overflows" sends its
    reader back to the browser to find out what."""
    failures = interact.render_version(browser, serve(SPILLING_PAGE))

    assert [
        f
        for f in failures
        if "<div id=too-wide> is set" in f and "px past the column" in f
    ]
    assert not [f for f in failures if "scrolls sideways" in f], (
        "the window absorbed it, which is what leaves this reading the only one that sees it"
    )


# Two wrappers that generate no box, differing only in whether anything inside them does.
# `#veiled` is the shape the vocabulary shipped while a suggestion was display: contents,
# and any page can still write in a line — it is the control: the gate must not report
# it, or it reports every page that styles a wrapper away. `#ghost` is the same wrapper
# with its words loose inside it, where there is nothing at all for a mark to hang on.
UNMARKABLE_PAGE = LONG_PAGE.replace(
    "</main>",
    "<div id='veiled' style='display: contents'>"
    "<p id='seen'>Words in a box of their own.</p></div>"
    "<div id='ghost' style='display: contents'>Words in no box at all.</div>\n</main>",
)


def test_the_render_gate_reports_words_no_mark_can_be_shown_on(browser, serve):
    """An element the reader can see and no mark can be drawn on, which the gate reads
    without pressing a key.

    The marks are the ask walk's ring and an element-anchored comment's outline, and both
    need a box. An element with `display: contents` generates none, so its own rect is the
    empty one every rect starts as — zero-sized at the document's origin — and the runtime
    hangs the mark on the boxes the element shows through instead. `#veiled` has one and
    is fine. `#ghost` has none, and there the paint has nowhere to land: this is the fault
    that reached a reader as `n` appearing to do nothing at all, on a page whose remaining
    asks were all suggestions, while the gate rendered it green.

    TINY_BOXES stands next to this reading and cannot take it: `checkVisibility()` is false
    for an element with no box, so it filters out exactly the elements at issue."""
    failures = interact.render_version(browser, serve(UNMARKABLE_PAGE))

    assert [f for f in failures if "<div id='ghost'>" in f and "no box to mark" in f], (
        f"the gate said nothing about words no mark can be shown on: {failures}"
    )
    assert not [f for f in failures if "veiled" in f or "seen" in f], (
        "a wrapper whose words are in a box of their own is what every suggestion is, "
        f"and the gate reported it: {failures}"
    )


# The shapes a float takes at the column's edge. The first three are laid out from the
# same left content edge, so the only difference is how far each one's own negative
# margin carries it: far enough and the whole box is out in the margin, which is what a
# sidenote is; not far enough and the box straddles the edge, which is a spill. The
# fourth says the same side in the logical spelling, and the fifth is the run of prose a
# resident holds — every one of which inherits the box its parent put out there.
FLOATING_PAGE = LONG_PAGE.replace(
    "</main>",
    "<div id='in-the-margin' style='float: left; clear: left; width: 180px;"
    " margin-left: -204px'>Beside <code id='inner-word'>--flag</code>.</div>"
    "<div id='half-out' style='float: left; clear: left; width: 180px;"
    " margin-left: -90px'>Across.</div>"
    "<div id='logical' style='float: inline-start; clear: left; width: 180px;"
    " margin-left: -204px'>Beside.</div>"
    "<div id='off-window' style='float: left; clear: left; width: 180px;"
    " margin-left: -900px'>Gone.</div>\n</main>",
)


def test_the_render_gate_tells_a_float_in_the_margin_from_one_spilling_out_of_it(
    browser, serve
):
    """What tells a margin resident from a spill is where its box sits: clear of the
    column on the side it floats to, or across the edge it started inside. Both halves
    are load-bearing, and the second is the one a shortcut drops — exempting floats
    outright would retire this check for every element that happens to carry one, and
    the gate reads `position` alone no longer, a sidenote being a float.

    Both readings run up the ancestors, because a resident answers for what it holds. A
    sidenote is prose and carries the code, links and emphasis prose carries; asking
    only the element itself named every one of them as spilling out of a column it was
    never in, which is a handover refused over the words the idiom exists to hold.

    And the side is resolved rather than string-matched: `float` computes to whichever
    of its four values was written, so `inline-start` — the same left edge — read as
    neither 'left' nor 'right' and failed the page for it."""
    failures = interact.render_version(browser, serve(FLOATING_PAGE))

    assert [
        f
        for f in failures
        if "<div id=half-out> is set" in f and "past the column" in f
    ]
    assert not [f for f in failures if "in-the-margin" in f or "logical" in f], (
        "a float whose own margin carried it clear of the column is where it meant to be"
    )
    assert not [f for f in failures if "inner-word" in f], (
        "a resident's own words were named for standing where their parent put them"
    )
    # Clear of the column and clear of the window with it. Body is the page's scroller
    # and scrollLeft never runs below zero, so the sideways reading is blind to this one
    # and the margin exemption would carry it straight through.
    assert [
        f
        for f in failures
        if "<div id=off-window> is drawn" in f and "outside <body>" in f
    ], "a float carried off the edge of the window went out with the handover"


SIDENOTE_IN_A_WIDGET = LONG_PAGE.replace(
    "</main>",
    """<lf-options id="where" choose>
  <lf-option id="opt-a"><strong>First</strong>
    <aside class="sidenote" id="boxed-note">Measured over a quarter.</aside>
    <p>An option carrying a note written inside it.</p>
  </lf-option>
  <lf-option id="opt-b"><strong>Second</strong> The other one.</lf-option>
</lf-options>
</main>""",
)


# A note written level with a change, which is the one arrangement that puts two
# residents of the right margin on the same line.
NOTE_BESIDE_A_CHANGE = LONG_PAGE.replace(
    "</main>",
    """<aside class="sidenote" id="level-note">Measured over a quarter, and the number
moved twice inside it.</aside>
<lf-suggestion id="sug-level">
  <lf-old><p id="old-level">About three thousand writes a second at peak.</p></lf-old>
  <lf-new><p>3,400 writes a second at p99, over the last quarter.</p></lf-new>
</lf-suggestion>
</main>""",
)


def test_a_change_may_be_decided_over_the_note_it_stands_level_with(browser, serve):
    """Both residents of the right margin are pinned by the flow — the controls level
    with the change they decide, the note level with the block it annotates — so on a
    page that writes one beside the other, neither can step aside and the controls are
    drawn over the note's first line. That is the arrangement leaf ships, so the gate
    that reads words drawn on words has to let it through, or every page composing the
    two idioms is refused at handover.

    The exemption is the float rather than the control, which is what keeps it from
    swallowing the check it lives in: the same row docks into the flow when it finds no
    room, and a docked row covering a word is a fault again. So the docked reading is
    asserted beside the floating one — a gate that has only ever passed has been tested
    for nothing, and this one is one predicate away from exempting every control there
    is."""
    url = serve(NOTE_BESIDE_A_CHANGE)
    page, errors = open_page(browser, url)
    page.locator("#sug-level").scroll_into_view_if_needed()
    geometry = """() => {
        const note = document.getElementById('level-note').getBoundingClientRect();
        const row = document.querySelector('.lf-sug-actions');
        const b = row.getBoundingClientRect();
        return {position: getComputedStyle(row).position,
                across: Math.min(note.right, b.right) - Math.max(note.left, b.left),
                down: Math.min(note.bottom, b.bottom) - Math.max(note.top, b.top)};
    }"""
    level = page.evaluate(geometry)
    covered = page.evaluate(interact.COVERED_WORDS)
    # The same row, docked: the theme releases the rail below its breakpoint, and the
    # module observes the resulting body geometry on its next layout frame. What the
    # gate asks is the computed position, so narrowing the window is how the other half
    # of the predicate is reached — and the class is the fact that frame states.
    resized(page, 800, 900)
    page.wait_for_function(
        "() => document.querySelector('.lf-sug-actions')"
        ".classList.contains('lf-docked')"
    )
    docked = page.evaluate(geometry)
    page.close()

    assert level["position"] == "absolute", (
        f"the row never hung in the margin, so nothing here was tested: {level}"
    )
    assert level["across"] > 2 and level["down"] > 2, (
        f"the controls and the note never met, so this proves nothing: {level}"
    )
    assert not [f for f in covered if "level-note" in f], (
        f"a change's controls were refused the margin they are decided in: {covered}"
    )
    assert docked["position"] == "static", (
        f"the row stayed out of the flow at a width that docks it: {docked}"
    )
    assert errors == []


def test_the_covered_words_gate_still_reads_a_control_in_the_flow(browser, serve):
    """The other half of the exemption above, put back as a bug: a control the widget
    hangs out of the flow is answered for, and one standing in the flow is a resident
    like any other. Written against a control the page positions itself, because the
    predicate is the computed position rather than any widget's name.

    `relative` is the case it is written for, being the near-miss that reads as
    positioned and is not: the box keeps its place in the flow and is painted offset
    from it, so a control nudged a pixel would have carried the whole exemption with it
    had the predicate been everything that isn't static."""
    covering = LONG_PAGE.replace(
        "</main>",
        "<p id='under'>A paragraph with something standing on it.</p>"
        "<span data-lf-offer role='button' id='over' style='position: relative;"
        " display: block; margin-top: -28px'>Covering words</span>\n</main>",
    )
    page, errors = open_page(browser, serve(covering))
    page.locator("#under").scroll_into_view_if_needed()
    covered = page.evaluate(interact.COVERED_WORDS)
    page.close()
    assert [f for f in covered if "id=under" in f and "id=over" in f], (
        f"a control the page put in the flow covered a paragraph unreported: {covered}"
    )
    assert errors == []


def test_the_render_gate_reports_a_sidenote_a_box_clips_away(browser, serve):
    """A choose group clips its own box, so a note pulled into the page's margin from
    inside one is painted nowhere. Every other reading calls that well — the column
    check excuses a margin resident, checkVisibility() is true of a clipped box so
    screen and print agree, and the copy, which withholds the clip, shows the words the
    live page dropped — so the reader is the only party who loses them, and a reviewer
    proofing the export sees a note that never reached anybody.

    The question is put to every box rather than to floats alone, since the excuse the
    note is claiming — my container took my overflow, so it answers for me — is granted
    to whatever stands inside one. And the boxes that clip are the minority: a section,
    a tab panel and a disclosure all pass a note through to the margin. So the gate
    names the one that doesn't, at handover, to the one party who can still move it."""
    url = serve(SIDENOTE_IN_A_WIDGET)
    page, errors = open_page(browser, url)
    # elementFromPoint answers about the viewport, so the question can only be put to a
    # note that is in it — LONG_PAGE puts this one four thousand pixels down. The group
    # is what gets scrolled to, never the note: `overflow: hidden` refuses a reader and
    # not a script, so scrolling to the clipped element hands the group's own box
    # sideways until the note is inside it, and the test then measures a page it made.
    page.locator("#where").scroll_into_view_if_needed()
    seen = page.evaluate("""() => {
        const n = document.getElementById('boxed-note');
        const b = n.getBoundingClientRect();
        const mid = document.elementFromPoint(b.left + b.width / 2, b.top + b.height / 2);
        // The note or something of its own, never an ancestor: a clipped note leaves
        // the point to <body>, which contains it and paints none of it.
        return {painted: !!mid && (n === mid || n.contains(mid)),
                at: mid && mid.tagName};
    }""")
    failures = interact.render_version(browser, url)
    page.close()

    assert not seen["painted"], (
        f"nothing clipped the note, so this proves nothing about the gate: {seen}"
    )
    assert [
        f
        for f in failures
        if "<aside id=boxed-note> is drawn" in f
        and "outside <lf-options id=where>" in f
    ], f"a note the reader never sees went out with the handover: {failures}"
    assert errors == []


# Boxes over their container, differing only in what holds them and how. The first two
# are the rule and neither alone proves it: a page that named both would refuse every
# wide table the theme puts in a scroller, and one that named neither is the gate before
# it could see a clipped box at all. The third says which box holds this one — it is
# written inside a clipping box and placed against the column, so the markup and the
# containing blocks answer differently and only one of them paints. The fourth is that
# question the other way up: containment makes a static box the containing block of what
# it then cuts, while the overflow every gate before this one read computes `visible`.
# The fifth is a box that says it cuts. The sixth is where the cut falls: a border hides
# what is drawn under it, and a border box says nothing about that. The last pair is why
# the report is suppressed per container rather than per subtree — nested, and lost out
# of two different boxes by two very different amounts.
OVER_ITS_CONTAINER = LONG_PAGE.replace(
    "</main>",
    "<div id='clipping' style='width: 300px; overflow: hidden'>"
    "<div id='eaten' style='width: 420px'>Nobody sees the end of this.</div></div>"
    "<div id='scrolling' style='width: 300px; overflow-x: auto'>"
    "<div id='reachable' style='width: 420px'>This one scrolls into view.</div></div>"
    "<div id='holding' style='width: 300px; height: 40px; overflow: hidden'>"
    "<div id='hung' style='position: absolute; width: 420px'>Placed, so this one "
    "holds it not at all.</div></div>"
    "<div id='contained' style='width: 300px; height: 40px; contain: paint'>"
    "<div id='cut-by-paint' style='position: absolute; width: 420px'>Containment cuts "
    "this one while overflow says visible.</div></div>"
    "<div id='telling' style='width: 300px; overflow: hidden; "
    "text-overflow: ellipsis; white-space: nowrap'>"
    "<span id='told'>A line long enough to run past the end of the box it is written "
    "inside, which says so with an ellipsis.</span></div>"
    "<div id='bordered' style='width: 300px; border-left: 20px solid #888; "
    "overflow: hidden'>"
    "<div id='under-border' style='margin-left: -20px; width: 300px'>The first 20px of "
    "this are behind the border.</div></div>"
    "<svg id='drawn' width='300' height='60' xmlns='http://www.w3.org/2000/svg'>"
    "<foreignObject width='120' height='40'>"
    "<div xmlns='http://www.w3.org/1999/xhtml' style='width: 128px'>The drawing's own "
    "accounting.</div></foreignObject></svg>"
    "<div id='barely' style='width: 300px; overflow: hidden'>"
    "<div id='over-by-three' style='width: 303px'>Three pixels over this one."
    "<div id='inner-box' style='position: relative; width: 200px; height: 40px; "
    "overflow: hidden'>"
    "<div id='over-by-far' style='position: absolute; left: 0; width: 600px'>Four "
    "hundred over that one.</div></div></div></div>"
    "\n</main>",
)


def test_the_render_gate_reports_a_box_its_container_clips_away(browser, serve):
    """A box need not float to be lost. The column reading hands a whole subtree to the
    first ancestor that takes its own overflow, and that container answers for what ran
    out of it only where the reader can still get to it — so the gate asks which kind of
    container it was, of every box rather than of floats alone.

    And asks it of what the container does rather than of its overflow, which is one of
    three ways to draw nothing past an edge: paint containment and content-visibility
    cut a box while overflow computes `visible`. Containment carries the placed case
    too, being what makes a static box the containing block of the box it then cuts —
    the converse of the box hung off `holding`, which is placed out of a clip that never
    held it."""
    failures = interact.render_version(browser, serve(OVER_ITS_CONTAINER))

    assert [
        f
        for f in failures
        if "<div id=eaten> is drawn" in f and "outside <div id=clipping>" in f
    ], f"a box drawn nowhere went out with the handover: {failures}"
    assert not [f for f in failures if "reachable" in f or "scrolling" in f], (
        "a box the reader scrolls to is where its container means it to be"
    )
    assert not [f for f in failures if "id=hung>" in f and "id=holding>" in f], (
        "a placed box was laid at the door of a static box that never held it"
    )
    assert not [f for f in failures if "id=told>" in f], (
        "a box that marks its own cut was refused for making it"
    )
    assert not [f for f in failures if "foreignobject" in f], (
        "a drawing's own accounting inside its svg read as the page losing words"
    )
    assert [
        f
        for f in failures
        if "<div id=under-border> is drawn" in f and "outside <div id=bordered>" in f
    ], f"a box drawn under a border read as inside it: {failures}"
    assert [
        f
        for f in failures
        if "<div id=over-by-far> is drawn" in f and "outside <div id=inner-box>" in f
    ], f"a 3px loss out of one box hid a 400px loss out of another: {failures}"
    assert [
        f
        for f in failures
        if "<div id=cut-by-paint> is drawn" in f and "outside <div id=contained>" in f
    ], f"a container that cuts by containment answered for nothing: {failures}"


SCROLLED_CONTAINER = LONG_PAGE.replace(
    "</main>",
    "<div id='rolled' style='width: 300px; overflow-x: auto'>"
    "<div id='riding' style='width: 900px'>Where the content of a scrolled box "
    "starts.</div></div>\n</main>",
)


def test_the_render_gate_reads_a_scrolled_container_from_its_content(browser, serve):
    """A scroller's rects say where it is scrolled to, not how far its content reaches,
    and the gate reads a page the reader has already worked: the runtime scrolls a
    board or a table sideways to bring a comment's anchor into view. Read off the rects,
    every box at the content's start then sits left of the container drawing it and
    reports as lost out of a box showing it perfectly — a handover refused over a page
    that is exactly as its author left it.

    The scroll is put on from outside, through the stand-in `primed` supplies, because
    the page's own CSP takes no inline script and the gate opens its own page. It is
    re-applied each frame so it stands for the whole of the gate's read."""

    def scroll_it(page):
        page.add_init_script(
            "addEventListener('DOMContentLoaded', () => {"
            "  const hold = () => {"
            "    const box = document.getElementById('rolled');"
            "    if (box) box.scrollLeft = 400;"
            "    requestAnimationFrame(hold);"
            "  };"
            "  hold();"
            "});"
        )

    url = serve(SCROLLED_CONTAINER)
    failures = interact.render_version(primed(browser, scroll_it), url)

    assert not [f for f in failures if "riding" in f or "rolled" in f], (
        f"a scrolled box was read as having lost what it was scrolled past: {failures}"
    )


def test_a_page_hands_its_note_strip_back_when_the_panel_takes_the_room(browser, serve):
    """The margin form is granted by a media query, which asks the window — and the
    panel takes 420px off the page's box without the window changing at all. Held
    through that, a 1024px window left this page's column 151px wide and its widest
    widgets painting out past the edge of it. So syncLayout asks the theme's own floor
    of the box instead and says whether the page is cramped, and the strip stands down
    for as long as it is.

    Nothing else can see this posture. `version check --render` and the render sweep
    both open a 1200px window with no panel in it, which is the width the query is
    right at, so the gate that reads a spill is reading the one layout where there
    isn't one.

    Three readings, because each of the other two designs passes one of them. A page
    that never had a note in the margin passes the cramped read on its own; a strip
    released on every open panel, room or no room, passes that one too — and it is the
    third that says no, the room being there on a wide window and the notes staying
    where the reader had them."""
    example = next(p for p in EXAMPLES if p.stem == "design-decision")
    url = serve(example)
    page, errors = open_page(browser, url)
    reading = """() => {
        const note = document.querySelector('aside.sidenote');
        const main = document.querySelector('main'), s = getComputedStyle(main);
        return {float: getComputedStyle(note).float,
                cramped: document.body.hasAttribute('data-lf-cramped'),
                column: Math.round(main.getBoundingClientRect().width
                    - parseFloat(s.paddingLeft) - parseFloat(s.paddingRight))};
    }"""
    roomy = page.evaluate(reading)
    resized(page, 1024, 900)
    page.locator(".lf-comments").click()
    panel_settled(page)
    cramped = page.evaluate(reading)
    misplaced = page.evaluate(interact.MISPLACED_BOXES)
    # Wide enough that the panel's 420px still leaves the floor a clear margin rather
    # than the twenty-odd pixels 1600 leaves it: the reading is meant to say the strip
    # survives a window with room for both, not to sit on the boundary and report which
    # side of it this month's --note falls.
    resized(page, 1728, 900)
    wide = page.evaluate(reading)
    page.close()

    assert roomy["float"] == "right", (
        f"no note stood in the margin to begin with, so this proves nothing: {roomy}"
    )
    assert cramped["float"] == "none", (
        f"the strip outlived the room for it: {cramped}, {misplaced}"
    )
    assert misplaced == [], (
        f"content set outside a column the strip had crushed: {misplaced}"
    )
    assert wide["float"] == "right", (
        f"a window wide enough for both moved the notes anyway: {wide}"
    )
    assert errors == []


# The two edges the reader draws, and what a reading of either has to know: a page that
# offers the region, what puts it up, the region's own selector, which side of the window
# it is held to, and the numbers the runtime holds it to. Two records rather than two
# tests, because the whole claim of `drawnEdge` is that the two are one piece of furniture
# reflected — a reading written for the panel alone would go on passing on the day the
# tray's edge stopped working, and the tray's edge exists precisely because the panel's
# did not have to be written a second time.
#
# `html` is a call rather than the markup, because the page the trays need is declared
# with the other tray readings a long way below here, and a parametrize list is read at
# import. `squeeze` is the window that has no room for what the reader chose and the width
# the region stands at there — per edge, because each is capped against its own half of a
# window and covers the page at a different one.
EDGES = [
    SimpleNamespace(
        name="comments",
        html=lambda: LONG_PAGE,
        comments=1,
        stand=lambda page: page.locator(".lf-comments").click(),
        region=".lf-panel",
        side="right",
        store="lf-panel-width",
        wide=420,
        squeeze=(1000, 500),
    ),
    SimpleNamespace(
        name="trays",
        html=lambda: ASKS_PAGE,
        comments=0,
        stand=lambda page: page.keyboard.press("a"),
        region=".lf-asks-panel",
        side="left",
        store="lf-tray-width",
        wide=300,
        squeeze=(800, 400),
    ),
]
EDGE_IDS = [edge.name for edge in EDGES]


def edge_settled(page, edge):
    """Wait for the region to stand and for the page to finish making room for it.

    Two animations, on two elements, and `panel_settled`'s reasoning covers both: the
    strip the page yields is a transition on body, and the region's arrival is its own
    slide. A geometry read between them is a read of a box still under a transform.
    """
    expect(page.locator(edge.region)).to_be_visible()
    page.wait_for_function(
        "(region) => document.body.getAnimations().length === 0"
        " && document.querySelector(region).getAnimations().length === 0",
        arg=edge.region,
    )


def geometry(page, edge):
    """What the edge reads back as, and what the page has left beside it.

    The two numbers are one fact asked from both sides: the strip is body's margin and
    the region's own box, and the whole point of the width being the reader's is that
    nothing may hold a copy of it their gesture doesn't reach.
    """
    return page.evaluate(
        """([region, side, store]) => {
            const box = document.querySelector(region).getBoundingClientRect();
            const body = document.body.getBoundingClientRect();
            return {
                width: Math.round(box.width),
                edge: Math.round(side === 'right' ? box.left : box.right),
                page: Math.round(side === 'right' ? body.right : body.left),
                chosen: localStorage.getItem(store),
            };
        }""",
        [edge.region, edge.side, edge.store],
    )


def draw_edge(page, edge, by):
    """Draw the region's edge `by` pixels wider, as a hand on it would.

    Whole pixels, per `select`'s reason (tests/CLAUDE.md): a press on a fractional point
    is a press the browser is free to round somewhere else. In steps, because one jump
    from press to release is a drag with no `pointermove` between its ends, and the move
    is the whole of what this gesture is made of. Wider is away from the side the region
    is held to, which is the reading the runtime makes of the same gesture.
    """
    box = page.locator(f"{edge.region} .lf-edge").bounding_box()
    x, y = math.floor(box["x"] + box["width"] / 2), math.floor(box["y"] + 200)
    page.mouse.move(x, y)
    page.mouse.down()
    page.mouse.move(x + (by if edge.side == "left" else -by), y, steps=8)
    page.mouse.up()
    # The slide stands down for the length of a drag and comes back at its end, so what
    # is waited on is the page holding still rather than a transition finishing — which
    # `panel_settled` reads the same way, and which is empty here on both counts.
    page.wait_for_function("() => document.body.getAnimations().length === 0")


@pytest.mark.parametrize("edge", EDGES, ids=EDGE_IDS)
def test_the_reader_draws_an_edge_to_the_width_they_want(browser, serve, edge):
    """A conversation about a table wants room a conversation about a sentence does not,
    and a tray of long names wants room a tray of short ones does not; only the reader
    looking at one knows which this is. So each region's edge is a thing they take hold
    of, and the page yields exactly the strip they leave it.

    Both sides of that strip are read, because the failure this is written against does
    not show on either alone: a region that resizes while the page keeps yielding the old
    margin lays out perfectly well, with a band of page underneath it or a band of nothing
    beside it, and either is a width stated twice by two writers who have come apart. They
    are one number here — the property the runtime writes — and the reading is what says
    so.

    Then the same edge from the keyboard, because a reader who is not holding a pointer is
    still reading the same page, and then a reload, because a width set once and lost on
    the next version is a width they would have to set on every revision."""
    page, errors = open_page(browser, serve(edge.html(), comments=edge.comments))
    edge.stand(page)
    edge_settled(page, edge)
    default = geometry(page, edge)

    draw_edge(page, edge, 160)
    drawn = geometry(page, edge)

    # Focus lands on the edge with the drag, so the arrows are live on what the hand was
    # just holding; the press states that in the form a reader without a pointer makes it.
    # Toward the side the region is held to narrows it.
    page.locator(f"{edge.region} .lf-edge").press(
        "ArrowRight" if edge.side == "right" else "ArrowLeft"
    )
    page.wait_for_function("() => document.body.getAnimations().length === 0")
    stepped = geometry(page, edge)

    page.reload(wait_until="load")
    page.wait_for_function(BOTH_STAMPS)
    edge_settled(page, edge)
    returned = geometry(page, edge)
    page.close()

    assert default["width"] == edge.wide, (
        f"the region did not start at the width a reader who has said nothing gets: "
        f"{default}"
    )
    assert drawn["width"] == edge.wide + 160, (
        f"the edge did not follow the hand: {default} then {drawn}"
    )
    assert drawn["page"] == drawn["edge"], (
        f"the page yielded a strip of its own rather than the one the region took: {drawn}"
    )
    assert drawn["chosen"] == str(edge.wide + 160), (
        f"the reader's width was not kept: {drawn}"
    )
    assert (stepped["width"], stepped["page"]) == (
        drawn["width"] - 24,
        stepped["edge"],
    ), f"the arrow moved something other than the edge and the page with it: {stepped}"
    assert returned["width"] == stepped["width"], (
        f"the width did not survive the reload a version switch makes: {returned}"
    )
    assert errors == []


@pytest.mark.parametrize("edge", EDGES, ids=EDGE_IDS)
def test_a_window_with_no_room_for_a_chosen_width_does_not_un_choose_it(
    browser, serve, edge
):
    """A region may take half of a window it stands beside and no more — the same bargain
    the covering breakpoint strikes one window down, that the page keeps at least what the
    region takes. A window that shrinks past that is a window, not a retraction: the reader
    said 580 once, and a laptop lid opened narrower is not them saying 400 instead.

    So the choice and the standing width are two facts. Clamping the stored one would read
    identically on the narrow window and lose the reader's answer for good on the wide one
    they came back to, which is the failure this reading is here to catch — the third
    geometry below is the whole of it."""
    narrow, stands = edge.squeeze
    page, errors = open_page(browser, serve(edge.html(), comments=edge.comments))
    edge.stand(page)
    edge_settled(page, edge)
    draw_edge(page, edge, 160)
    drawn = geometry(page, edge)

    resized(page, narrow, 900)
    page.wait_for_function("() => document.body.getAnimations().length === 0")
    squeezed = geometry(page, edge)

    resized(page, 1400, 900)
    page.wait_for_function("() => document.body.getAnimations().length === 0")
    roomy = geometry(page, edge)
    page.close()

    assert drawn["width"] == edge.wide + 160, f"the drag did not land: {drawn}"
    assert squeezed["width"] == stands, (
        f"a {narrow}px window left the page less than the region took: {squeezed}"
    )
    assert squeezed["page"] == squeezed["edge"], (
        f"the page yielded a strip the region was not standing in: {squeezed}"
    )
    assert squeezed["chosen"] == str(edge.wide + 160), (
        f"the narrow window un-said what the reader had said: {squeezed}"
    )
    assert roomy["width"] == edge.wide + 160, (
        f"the width the reader chose did not come back with the room for it: {roomy}"
    )
    assert errors == []


def test_both_trays_stand_on_the_one_edge_the_reader_drew(browser, serve, other_leaf):
    """Leaves and asks are the same furniture at two scopes, one at a time on one side of
    the window, so the width is the side's rather than either tray's. A reader who drew
    the edge out to read long names has drawn the edge, and finding the other tray back
    at its default would be one fact kept in two places — which is what a width per tray
    would have been, and what the shared property is instead.

    The `other_leaf` fixture is the whole reason there is a second tray to swap to: a
    tray of one — the page the reader is already on — is not worth a control, so without
    a neighbour `l` is dead."""
    page, errors = open_page(browser, serve(ASKS_PAGE))
    trays = EDGES[1]
    trays.stand(page)
    edge_settled(page, trays)
    draw_edge(page, trays, 160)

    page.keyboard.press("l")
    expect(page.locator(".lf-others-panel")).to_be_visible()
    page.wait_for_function(
        "() => document.querySelector('.lf-others-panel').getAnimations().length === 0"
    )
    leaves = page.evaluate(
        "() => document.querySelector('.lf-others-panel').getBoundingClientRect().width"
    )
    page.close()

    assert round(leaves) == trays.wide + 160, (
        f"the second tray came up at a width the reader had already moved: {leaves}"
    )
    assert errors == []


def test_a_tray_that_takes_a_strip_is_counted_against_the_margins_floor(browser, serve):
    """The theme's margin idioms are granted by a media query, which asks the window; what
    they hang in is the page's own box, which is the window less whatever the chrome holds
    of it. The panel's strip was counted there and the tray's was not, so a 1200px window
    with a tray standing granted a sidenote its margin against a 900px page — 84px under
    the floor the theme states, on the most ordinary window there is.

    Read as the veto rather than as a note's position, because the veto is the fact and a
    note is one idiom that spends it: a reading of the note would go on passing the day a
    second idiom stopped asking. Both states, because the attribute standing permanently
    would read the same way here and would cost every wide page its margins."""
    page, errors = open_page(browser, serve(ASKS_PAGE))
    resized(page, 1200, 900)
    cramped = "() => document.body.hasAttribute('data-lf-cramped')"
    room = page.evaluate(cramped)

    page.keyboard.press("a")
    edge_settled(page, EDGES[1])
    standing = page.evaluate(cramped)

    page.keyboard.press("a")
    expect(page.locator(".lf-asks-panel")).to_be_hidden()
    page.wait_for_function("() => document.body.getAnimations().length === 0")
    given_back = page.evaluate(cramped)
    page.close()

    assert not room, "a 1200px window with no tray was already short of the floor"
    assert standing, (
        "the tray took 300px out of a 1200px page and the margins were granted anyway"
    )
    assert not given_back, "the page kept the veto after the tray gave its strip back"
    assert errors == []


# The room, sampled every frame for as long as a slide lasts. A property is asked of the
# root rather than of any element that spends it, because it is the fact and an exhibit is
# one reader of it.
ROOM_EVERY_FRAME = """(frames) => {
  window.__room = [];
  // The first sample is taken now rather than on the first frame, so the width before the
  // press is always in the trace: a frame is free to land after the keypress that follows
  // this call, and a trace that opens after the strip is taken has one value in it and
  // nothing to compare.
  const tick = () => {
    window.__room.push(
      getComputedStyle(document.documentElement).getPropertyValue('--lf-room'));
    if (window.__room.length < frames) requestAnimationFrame(tick);
  };
  tick();
}"""


def test_the_room_does_not_flicker_while_a_strip_arrives(browser, serve, other_leaf):
    """The room a wide exhibit may take is the page's box less the strips the chrome
    holds, and for the fifth of a second a strip takes to arrive that box is neither the
    width the page has nor the one it is going to. Written as the box minus the strip the
    margin has not taken yet, the two readings are in different number systems — a client
    box is an integer and a transitioning margin is not — and the sum landed a pixel either
    way on alternate frames.

    A pixel is nothing to look at and the flicker is not the failure. Each flip is a
    relayout of every exhibit on the page, made from inside the observation that asked for
    it, and Chrome answers a loop of those on the window's error channel and nowhere else:
    the first sight of it was a press sweep going red on one example with nothing on screen
    to say why.

    So the reading is of the property rather than of anything laid out from it, and what it
    asks is that the room never returns to a value it has left. That is true of a slide
    both ways — arriving, the room is stated at once and holds; leaving, it grows back
    frame by frame — and it is false the moment two readings disagree by a pixel."""
    page, errors = open_page(browser, serve(ASKS_PAGE))
    resized(page, 1200, 900)
    page.evaluate(ROOM_EVERY_FRAME, 60)
    page.keyboard.press("a")
    edge_settled(page, EDGES[1])
    page.wait_for_function("() => window.__room.length >= 60")
    trace = page.evaluate("() => window.__room")
    page.close()

    steps = [room for i, room in enumerate(trace) if i == 0 or room != trace[i - 1]]
    assert len(steps) > 1, (
        f"the tray took no room out of the page, so nothing here was measured: {steps}"
    )
    assert len(steps) == len(set(steps)), (
        "the room went back to a width it had already left, which is a relayout of every "
        f"exhibit on the page on alternate frames: {steps}"
    )
    assert errors == []


# Enough code for the roles to differ from each other and from the block: a comment, a
# keyword, a string, a name, a number.
COLORED_CODE_PAGE = LONG_PAGE.replace(
    "</main>",
    """<pre id="snippet"><code class="language-python"># the ceiling doubles per approval
def ceiling(limit, approvals):
    return "over" if approvals > 12 else limit
</code></pre>
</main>""",
)

# Both bugs go back as CSS, which is the shape the regression takes for real: the
# attribute lands either way, and it is the stylesheet answering it that stops working.
# A rule at document level with the theme's own specificity, so the later one wins.
UNANSWERED_CODE_PAGE = COLORED_CODE_PAGE.replace(
    "</head>", "<style>[data-lf-syn] { color: inherit; }</style>\n</head>"
)
# What --syn-comment carried until this gate was written: 3.3:1 on --pre-bg, and the
# reading a user reported as the highlighting being gone.
FAINT_CODE_PAGE = COLORED_CODE_PAGE.replace(
    "</head>", '<style>[data-lf-syn="cm"] { color: #8b8577; }</style>\n</head>'
)

# A role that reads on the block and not on the tint one of its lines wears. The clean
# line comes first on purpose: a gate that stopped at a role's first span would take the
# 7.9:1 reading and never reach the 1.6:1 one two lines down, and a walkthrough's hi band
# is the surface where a code line is most often set on something other than --pre-bg.
TINTED_LINE_PAGE = LONG_PAGE.replace(
    "</head>", "<style>:root { --hi-tint: #6f6a60; }</style>\n</head>"
).replace(
    "</main>",
    """<lf-code id="tinted" language="python" hi="2"><pre>
first = "on the block's own colour"
second = "on the band"
</pre></lf-code>
</main>""",
)

# The same reading, in a shadow tree. lf-diff renders the page's words into one, so its
# spans are in no document.querySelectorAll — and the page carries no other code, so a
# probe that stopped at the boundary would sweep this and find nothing to say. The token
# is what goes back rather than a rule: a custom property inherits through the boundary
# where a selector does not, which is both why this reaches the spans and why a project's
# own palette reaches them too, gate or no gate.
SHADOWED_DIFF = """<lf-diff id="shadowed"><pre>
diff --git a/gateway/limits.py b/gateway/limits.py
--- a/gateway/limits.py
+++ b/gateway/limits.py
@@ -1,3 +1,4 @@
 def ceiling(limit, approvals):
-    return limit
+    # the ceiling doubles per approval
+    return "over" if approvals > 12 else limit
</pre></lf-diff>
</main>"""
SHADOW_CODE_PAGE = LONG_PAGE.replace(
    "</head>", "<style>:root { --syn-comment: #8b8577; }</style>\n</head>"
).replace("</main>", SHADOWED_DIFF)

# The other half of the boundary: what is painted behind a shadowed span is on the
# elements above the host, and a span at the top of a root has no parentElement to climb
# to. Today's theme hides that — the box a diff renders into carries an opaque --card, so
# a composite that stopped at the boundary would land on the same colour — which is a
# coincidence of the palette and not a reason to read the light tree. Flattening that one
# surface is all it takes to part them: the paper under it is what the reader has behind
# the comment, and against the white a stalled climb falls back to, a dark page's ink
# reads as either a pass or a failure that isn't on the screen.
FLAT_SHADOW_PAGE = LONG_PAGE.replace(
    "</head>", "<style>:root { --card: transparent; }</style>\n</head>"
).replace("</main>", SHADOWED_DIFF)


def test_the_render_gate_reports_code_the_reader_cannot_tell_from_its_block(
    browser, serve
):
    """Colouring code takes the runtime writing a role and the theme answering it, and
    the two meet only in the browser — so a stylesheet that stops answering, or answers
    too faintly, is a page of flat code and no error anywhere. Both failures are one
    question asked of the drawn page: can the reader tell this run of characters from
    the code around it.

    Each goes back as CSS and the gate is watched to fail, the third of them for the
    reading the other two can't distinguish: a role is fine on the block and unreadable
    on the tint one line wears, which a gate taking one colour per role never reaches,
    because the clean line comes first.

    The clean page is asserted to carry the roles first, because a block the tokenizer
    found nothing in passes this gate while proving nothing about it — which is the
    vacuous half of every reading here."""
    page, errors = open_page(browser, serve(COLORED_CODE_PAGE))
    roles = page.evaluate(
        "() => [...new Set([...document.querySelectorAll('[data-lf-syn]')]"
        ".map(s => s.dataset.lfSyn))].sort()"
    )
    page.close()
    assert errors == []
    assert "cm" in roles and len(roles) > 1, (
        f"this block came out {roles}, so it says nothing about a role going unread"
    )
    assert interact.render_version(browser, serve(COLORED_CODE_PAGE)) == []

    unanswered = interact.render_version(browser, serve(UNANSWERED_CODE_PAGE))
    assert [
        f
        for f in unanswered
        if f.startswith("[light] code marked cm is the ink of the code around it")
    ], unanswered

    faint = interact.render_version(browser, serve(FAINT_CODE_PAGE))
    assert [
        f for f in faint if f.startswith("[light] code marked cm reads at 3.3:1")
    ], faint
    assert not [f for f in faint if "code marked st" in f], (
        "only the role the style touched is unread, so the rest name the reading "
        "rather than the rule"
    )

    tinted = interact.render_version(browser, serve(TINTED_LINE_PAGE))
    assert [
        f for f in tinted if f.startswith("[light] code marked st reads at 1.6:1")
    ], (
        "the reading is of the surface each span is actually set on, not of one "
        f"block colour taken once per role — {tinted}"
    )

    page, errors = open_page(browser, serve(SHADOW_CODE_PAGE))
    where = page.evaluate(
        "() => ({ doc: document.querySelectorAll('[data-lf-syn]').length,"
        " shadow: [...document.querySelectorAll('*')].filter(e => e.shadowRoot)"
        ".flatMap(e => [...e.shadowRoot.querySelectorAll('[data-lf-syn=cm]')]).length })"
    )
    page.close()
    assert errors == []
    assert where == {"doc": 0, "shadow": 1}, (
        "this page has to put its only comment inside a shadow root, or the gate "
        f"passing it says nothing about the boundary — {where}"
    )
    shadowed = interact.render_version(browser, serve(SHADOW_CODE_PAGE))
    assert [
        f for f in shadowed if f.startswith("[light] code marked cm reads at 3.1:1")
    ], (
        "a widget that renders the page's words into a shadow root renders code the "
        f"reader still has to read — {shadowed}"
    )
    assert interact.render_version(browser, serve(FLAT_SHADOW_PAGE)) == [], (
        "with the box's own surface flattened, what is behind the comment is the "
        "page's paper — which is above the host, and reached by climbing out of the "
        "root rather than stopping where parentElement runs out"
    )


# Two sets, because pointing at a control and pressing it are different questions.
#
# What must hold still is everything a user aims at, however the widget that built
# one made it: the runtime's real buttons and selects, the spans `offer` builds, a tab, a
# pick mark, a reference. Naming the ways a control is constructed rather than the widgets
# that construct them is what lets a twelfth widget's join this sweep without editing it.
NEIGHBOUR = (
    "[data-lf-offer], [role=tab], [role=button], .lf-btn, .lf-pick, "
    "button, select, summary, a[href]"
)
# What this sweep presses is narrower, and both exclusions are about the press landing
# rather than about the control. A <select> opens a native popup the page cannot see and
# the next click closes instead of pressing — which is how this sweep first passed while
# pressing nothing at all, the shape of vacuous pass CLAUDE.md is about. A link is a
# user's control and its press is a scroll, so it belongs to the set above and has
# nothing here to disturb.
PRESS = "[data-lf-offer], [role=tab], [role=button], .lf-btn, .lf-pick, button, summary"

# The controls a press is aimed *past*: the ones sharing its parent, standing on the same
# line, and on screen at both ends of the gesture. Held in a JS array rather than looked
# up again afterwards, because identity has to survive a press that adds or removes a
# sibling; measured with offset*, which is the layout box before any transform, so a card
# still lifted under the pointer reads as the nothing it is.
#
# On screen is the load-bearing half. A control inside a fold the press opens was nowhere
# the user could aim, and one the press puts away — a suggestion's ✗ Reject, once ✓
# Accept has settled the pair — is not a control that moved. Both are the press doing what
# it was pressed for. `[hidden]` is asked separately because hidden="until-found", which is
# what a folded region wears, measures zero and still reports itself visible.
ON_SCREEN = "(n) => n.checkVisibility() && !n.closest('[hidden]') && n.offsetWidth > 0"
# What to call a control in a failure message. Its words are in it because they are
# usually the whole of what distinguishes one button in a row from the next — and out of
# the key it is looked up by, since a control that rewrites them (a count gaining a
# digit) is the same control saying something new.
NAMED = """(n) => n.tagName.toLowerCase()
    + (typeof n.className === 'string' && n.className.trim()
       ? '.' + n.className.trim().split(/\\s+/).join('.') : '')
    + ' ' + JSON.stringify((n.textContent || '').trim().slice(0, 24))"""
NEIGHBOURHOOD = f"""(el, sel) => {{
  const band = el.getBoundingClientRect();
  const sameLine = (n) => {{
    const r = n.getBoundingClientRect();
    return Math.min(r.bottom, band.bottom) - Math.max(r.top, band.top) > 1;
  }};
  window.__lfOnScreen = {ON_SCREEN};
  window.__lfNeighbours = [...el.parentElement.children]
      .filter((n) => n !== el && !n.contains(el))
      .flatMap((n) => (n.matches(sel) ? [n] : [...n.querySelectorAll(sel)]))
      .filter((n) => window.__lfOnScreen(n) && sameLine(n));
  return {{ names: window.__lfNeighbours.map({NAMED}), boxes: window.__lfBoxes() }};
}}"""
# The same capture, of the banner rather than of one control's line: every control the
# chrome is showing, held by identity so the news can rewrite their words without
# changing who they are.
BANNER_WATCH = f"""(sel) => {{
  window.__lfOnScreen = {ON_SCREEN};
  window.__lfNeighbours = [...document.querySelector(".lf-banner").querySelectorAll(sel)]
      .filter(window.__lfOnScreen);
  return {{ names: window.__lfNeighbours.map({NAMED}), boxes: window.__lfBoxes() }};
}}"""
# One reading, named once, so the rendered-frame wait and the assertion cannot measure
# differently.
DEFINE_BOXES = """() => { window.__lfBoxes = () => window.__lfNeighbours.map(
    (n) => window.__lfOnScreen(n)
      ? [n.offsetLeft, n.offsetTop, n.offsetWidth, n.offsetHeight] : null); }"""
# Nested animation-frame callbacks have one complete rendering turn between them, so
# this states rendered progress rather than elapsed time between two frame polls.
RENDERED = "() => new Promise(done => requestAnimationFrame(() => requestAnimationFrame(done)))"


def page_at_rest(page):
    """Render the known edge, finish finite motion, then render its ending."""
    page.evaluate(RENDERED)
    page.wait_for_function(f"() => ({interact.MOVING})().length === 0")
    page.evaluate(RENDERED)


def test_a_page_asking_for_sign_off_records_the_approval(browser, serve):
    """The declared ask puts the button there, and the press posts `done`.

    Drive the shipped browser through the real POST door, since a button that merely
    looks right says nothing about the event the agent's loop receives.
    """
    html = LONG_PAGE.replace(
        "<title>long</title>",
        '<title>long</title><meta name="lf-review" content="sign-off">',
    )
    page, errors = open_page(browser, serve(html))
    button = page.locator(".lf-signoff")
    expect(button).to_be_visible()
    expect(button).to_have_attribute(
        "title", "Approve this work; the page stays open for follow-up"
    )

    held = []
    page.route("**/api/event", lambda route: held.append(route))
    button.click()
    _until(page, lambda traffic: traffic.sends == 1, "held the approval in the wire")
    expect(button).to_be_disabled()
    expect(button).to_have_attribute("aria-busy", "true")
    button.dispatch_event("click")
    assert _traffic(page).sends == 1, "one approval press became two log events"

    held[0].continue_()
    page.unroute("**/api/event")
    round_trip(page)
    event = interact.read_events(serve.page_dir)[-1]
    assert (event["kind"], event["author"], event["version"]) == ("done", "user", 1)
    assert event["text"]
    expect(button).to_be_disabled()
    assert errors == []
    page.close()


def test_sign_off_waits_for_the_page_while_comments_stay_live(browser, serve):
    """Approval belongs to the presented page; runtime discussion does not wait for it."""
    html = LONG_PAGE.replace(
        "<title>long</title>",
        '<title>long</title><meta name="lf-review" content="sign-off">',
    )
    held = []
    page = browser.new_page()
    errors = watched(page)
    page.route("**/api/state*", lambda route: held.append(route))
    try:
        with page.expect_request("**/api/state*"):
            page.goto(serve(html), wait_until="load")
        page.wait_for_function("() => document.body.dataset.lfUpgraded === '1'")
        assert held, "the positive control did not hold the first state response"
        button = page.locator(".lf-signoff")
        expect(button).to_be_visible()
        expect(button).to_be_disabled()

        page.locator(".lf-comments").click()
        expect(page.locator(".lf-panel")).to_have_class(re.compile(r"\bopen\b"))

        held.pop(0).continue_()
        page.wait_for_function(BOTH_STAMPS)
        expect(button).to_be_enabled()
        assert errors == []
    finally:
        page.close()


def test_a_page_that_asks_nothing_carries_no_terminal_control(browser, serve):
    """A page that only informs ends its banner at Comments.

    The slot the approve button takes on a sign-off page stays empty here rather than
    picking up a neutral control, which is the fact a reader can see: an informational
    page asks them for nothing, so it hands them nothing to press.
    """
    page, errors = open_page(browser, serve(LONG_PAGE))
    # The banner is built in one pass, so a control standing in it is what makes the
    # absence beside it worth reading rather than a row that never rendered.
    expect(page.locator(".lf-comments")).to_be_visible()
    assert page.locator(".lf-signoff").count() == 0
    # The approve button is the row's last control where a page asks for one, and a
    # blanket-answer control inserts ahead of the version chooser, so the row ending
    # at Comments is the slot standing empty rather than merely unnamed.
    expect(page.locator(".lf-banner > *").last).to_have_class("lf-btn lf-comments")
    assert errors == []
    page.close()


def displaced(before, boxes):
    """Which of the watched controls are somewhere else, in the failure's own words.

    A control that has gone off screen reads None and is left out: it was put away
    rather than moved, which is a thing both sweeps below deliberately allow."""
    return [
        f"{name} moved by "
        f"{[round(a - b, 1) for a, b in zip(now, was)]} (left, top, width, height)"
        for name, was, now in zip(before["names"], before["boxes"], boxes)
        if now is not None and was != now
    ]


@pytest.mark.parametrize("example", EXAMPLES, ids=lambda p: p.stem)
def test_a_press_leaves_its_neighbours_where_they_were(browser, serve, example):
    """A press may change the page; it may not move the controls next to the one pressed.

    A user works by pointing, and the line a control stands on is where their next
    gesture is already aimed. What a press changes below it is content — a tab shows a
    different panel, a fold opens, a suggestion resolves, and the page under it moves
    because the user asked it to. What must not move is the row itself, because
    nothing was asked of it and it is the one thing the user is still using.

    Three shipped controls broke this rule, each by changing a metric to say something:
    a selected tab set in 600 weight, since a bolder label is a wider one, so the strip
    reshuffled under the pointer that had just pressed it; the sign-off button, whose
    "✓ Approved" is 12px narrower than "✓ Looks good", sliding the version chooser and
    the Comments button right; and a row-form pick mark, which took the room for the
    word it says on being pressed and dragged that row's § reference 54px left. None of
    them shows in a screenshot of either state, because every strip and every row lays
    out perfectly well on its own; it is the two states together that say anything.

    Two of the three are fixed by holding the widest word's room from the start. That
    room is measured at load rather than stated, because a number read once out of a
    browser covers the face it was read in and no other: the pick column's stood at 68px
    and went 2px short the first time this ran on Linux, whose system sans sets "your
    pick" wider than macOS's. This is what said so, and it says how late a stated number
    is caught — a platform late, and only where there is a second platform to run on.

    Driven over the corpus rather than per widget: a control this sweep has never heard
    of joins it by being pressable, which is the only property it reads.

    One press per page, because a press is a gesture made on the page as published and
    the state an earlier one leaves changes what a later one proves. Pressing straight
    down the document hid the sign-off button's 12px for exactly that reason: Comments
    comes first in the banner, and with the panel open the row is crowded enough that
    the status text takes up the slack instead of the buttons — a real regression,
    silently masked by the sweep's own previous gesture."""
    url = serve(example)
    page, errors = open_page(browser, url)
    page_at_rest(page)
    total = page.locator(PRESS).count()
    pressed, dirty = 0, False
    for i in range(total):
        if dirty:  # only a press dirties the page, and most of these indices skip
            # Reloading is not on its own a reset: the panel remembers whether it was
            # open and every unsent draft is the reader's (localStorage), while the
            # reading position is this tab's (sessionStorage) — all of them
            # deliberately. Left standing they decide what
            # the next press proves — an open panel crowds the banner enough that the
            # status text takes up a shrinking button's slack instead of the buttons, so
            # the sign-off regression this test was written for passed or failed
            # according to how many times the sweep had toggled Comments.
            page.evaluate("() => { localStorage.clear(); sessionStorage.clear(); }")
            # `load`, the edge the first visit took (`open_page`): network silence is
            # not a readiness fact and the two lines below are the ones that are, so
            # waiting it out only added its own 500ms quiet window to every reload
            # this sweep makes — a sixth of the test on the gallery, 50s to 42s.
            page.goto(url, wait_until="load")
            # Both stamps, which the reload has to earn again: half these controls are
            # the runtime's own, and the last of them arrive with the log rather than
            # with the upgrade. A list read before that is a short list, and a short list
            # skips by index rather than failing, which is how this sweep quietly stopped
            # pressing the sign-off button between one run and the next. It is the count
            # below that says so out loud — refuse the first poll of each navigation here
            # and every one of the thirteen examples fails on it.
            page.wait_for_function(BOTH_STAMPS)
            page_at_rest(page)
            dirty = False
            assert page.locator(PRESS).count() == total, (
                f"{example.name} has a different set of controls after a reload, so the "
                "indices this sweep walks name different things on either side of one"
            )
        page.evaluate(DEFINE_BOXES)
        control = page.locator(PRESS).nth(i)
        # A control the user can't press has no gesture to disturb anything. Both
        # spellings, because a span press can only ever wear the attribute.
        if not control.is_visible() or not control.is_enabled():
            continue
        if control.get_attribute("aria-disabled") == "true":
            continue
        label = control.evaluate(
            "(el) => el.tagName.toLowerCase() + ' '"
            "        + JSON.stringify((el.textContent || '').trim().slice(0, 24))"
        )
        before = control.evaluate(NEIGHBOURHOOD, NEIGHBOUR)
        if not before["names"]:
            continue
        control.click()
        pressed, dirty = pressed + 1, True
        # The press's own effect is synchronous; what follows it is the round trip the
        # press started and whatever its answer repaints, which is as much part of
        # pressing as the frame before it. A press that sent nothing is already round
        # tripped, so both kinds take the same rendered edge.
        round_trip(page)
        page_at_rest(page)
        moved = displaced(before, page.evaluate("() => window.__lfBoxes()"))
        assert not moved, (
            f"pressing {label} in {example.name} moved the controls beside it:\n  "
            + "\n  ".join(moved)
        )
    assert pressed, f"{example.name} pressed nothing, so it asserts nothing"
    assert errors == []
    page.close()


def aim_targets(page_dir):
    """Everything an ⌥-press can land on that something is waiting to answer.

    Every control however its widget built one, and every element of the vocabulary,
    whose handlers sit on the widget rather than on a control — an option is picked by
    clicking its prose. The vocabulary is read from the page's own registry rather than
    listed, so the twelfth widget is swept by existing. Prose has no handler at all, so
    one press into it proves what fifty would."""
    tags = ", ".join(
        t for t in interact.load_registry(page_dir) if not t.startswith("$")
    )
    return f":is({PRESS}, {tags}):not(.lf-chrome *)"


# Where in a target to aim, asked of the rendered page rather than assumed: near its
# leading corner, since the middle of a container is usually one of its children, and only
# where the point is really the target's — an element under the banner or clipped to
# nothing is somewhere no aim can land, which is a skip rather than a failure.
AIM_POINT = """(el) => {
  const r = el.getBoundingClientRect();
  const spots = [[r.left + Math.min(8, r.width / 2), r.top + Math.min(8, r.height / 2)],
                 [r.left + r.width / 2, r.top + r.height / 2]];
  for (const [x, y] of spots) {
    const at = document.elementFromPoint(x, y);
    if (at && (at === el || el.contains(at))) return [x, y];
  }
  return null;
}"""
# The promise itself, read where the runtime states it: the aim's box in the chrome's
# layer carries the aimed item's id (data-for, refreshAim's one write of it). The
# composer's own mark then stands on that same item once the press is made, so the box's
# answer before the press and the draft's after it agreeing is the promise being kept.
AIMED = """() => document.querySelector(".lf-aim")?.getAttribute("data-for") ?? null"""
# The item the draft stands on, which is not always the element wearing the outline: a
# mark hangs on the boxes its item shows through, and a display: contents wrapper shows
# through its slots. Reading the raw id said the promise was broken for every suggestion
# on every example — while the reading that had passed all along was the vacuous one, the
# outline sitting on a wrapper that draws nothing.
DRAFT_MARK = """() =>
  document.querySelector(".lf-mark-el.lf-pending")?.closest("[id]")?.id ?? null"""
# What the arm says about the next press, in the one property that is on screen before
# the box is read. Asked of body, where the aim declares it and from where it is
# inherited by everything on the page that doesn't state a cursor of its own.
AIM_CURSOR = """() => getComputedStyle(document.body).cursor"""
# Where focus ended up, which is the effect a press has that leaves no mark in the markup:
# `offer` gives every press it builds a tabindex, so a press the page received lands on
# the control, where the aim's own leaves focus to the composer it opened.
FOCUS_IN_PAGE = """() => {
  const at = document.activeElement;
  return !!at && at !== document.body && !at.closest(".lf-chrome");
}"""
# The page as against the layer over it, which is where an effect nobody asked for shows.
# Read as markup because a widget acting states itself there however it renders — an
# attribute picked, a panel hidden, an editor opened — and a sweep that knew which to look
# for would be a sweep that stops at the widgets it was taught.
#
# Except for an emptied class attribute, which is the outline coming off an element that
# had no class of its own: DOMTokenList leaves `class=""` behind, and that is a residue of
# the runtime's paint rather than anything the page says.
# Generated text is blanked before the compare, because a widget may render a clock
# and a clock is not a press: lf-agent's elapsed line re-renders on every poll, so the
# minute turning during a long sweep read as a press that had reached a widget. What the
# check is for survives untouched — a stray pick writes `chosen` on the option and a
# stray tab switch moves the panels' attributes, both of them authored rather than
# generated, and structure is compared either way.
PAGE_MARKUP = """() => [...document.body.children]
    .filter((n) => !n.classList.contains("lf-chrome"))
    .map((n) => {
        const c = n.cloneNode(true);
        for (const g of c.querySelectorAll("[data-lf-gen]")) g.textContent = "";
        if (c.dataset && c.dataset.lfGen !== undefined) c.textContent = "";
        return c.outerHTML;
    })
    .join("").replaceAll(' class=""', "")"""


def test_the_catalog_sidenote_can_be_aimed_whole(browser, serve):
    """The sidenote authors copy carries the identity its advertised aim needs.

    A handwritten fixture would prove the runtime and leave the catalog free to
    regress to an id-less note that renders normally but gives Alt nothing to outline.
    Drive that example itself through the whole gesture, from outline to anchored
    composer."""
    registry = interact.incoming_registry([interact.ASSETS, interact.BUNDLED])
    sidenote = registry["$idioms"]["aside.sidenote"]["example"]
    html = LONG_PAGE.replace(
        '<h1 id="t">Long</h1>', f'<h1 id="t">Long</h1>\n{sidenote}'
    )
    page, errors = open_page(browser, serve(html))
    note = page.locator("#logout-frequency")

    note.hover()
    page.keyboard.down("Alt")
    expect(page.locator(".lf-aim")).to_have_attribute("data-for", "logout-frequency")
    note.click()
    page.keyboard.up("Alt")

    expect(page.locator(".lf-composer")).to_be_visible()
    assert page.evaluate(DRAFT_MARK) == "logout-frequency"
    assert errors == []
    page.close()


@pytest.mark.parametrize("example", EXAMPLES, ids=lambda p: p.stem)
def test_an_aimed_press_does_only_what_the_outline_promised(browser, serve, example):
    """⌥-click takes the item under the pointer, and that is the whole of what it does.

    Holding ⌥ outlines what a click would take, which is a promise about the next press.
    The runtime used to read that press on the way back up, after every handler out on the
    page had already had it, so the press kept the promise and did something else besides:
    ⌥-clicking an option card opened the composer *and* picked the option, sending Claude a
    decision the user never made, while ⌥-clicking a tab's name aimed at the widget and
    switched the panel under it. Neither shows in the composer, which opens either way.

    So both halves are asserted together — the composer opens on the item that was
    outlined, and the page is exactly as it was, in its markup and in where its focus sits
    — over the corpus rather than over a case, because every widget that takes a press had
    this and none of them was ever told."""
    url = serve(example)
    page, errors = open_page(browser, url)
    targets = aim_targets(serve.page_dir)
    total = page.locator(targets).count()
    pressed = aimed = 0
    for i in range(total):
        # A control inside a fold or behind an unopened tab is nowhere a user can aim,
        # which is the press sweep's reading of the same question, and a point the banner
        # or a neighbour covers is not this target's press at all.
        target = page.locator(targets).nth(i)
        if not target.is_visible():
            continue
        # A wrapper with no box of its own — one a page's style leaves
        # display: contents — is nowhere a user can aim (AIM_POINT finds no point
        # in it either), and
        # scroll_into_view can wait on its stability forever when it stands inside
        # a table box (a specimen). Its slots are their own targets.
        if not target.evaluate("el => el.getClientRects().length"):
            continue
        target.scroll_into_view_if_needed()
        point = target.evaluate(AIM_POINT)
        if not point:
            continue
        label = target.evaluate(NAMED)
        before = page.evaluate(PAGE_MARKUP)
        page.mouse.move(*point)
        page.keyboard.down("Alt")
        promised = page.evaluate(AIMED)
        # The cursor is the other half of the same promise, and it is derived from the
        # same value the outline is: the hand where a press takes something, the arrow
        # where it takes nothing. Read off body, which is where the aim declares it —
        # a widget's own control still states its resting cursor, and does so whether or
        # not the key is down.
        assert page.evaluate(AIM_CURSOR) == ("pointer" if promised else "default"), (
            f"holding ⌥ over {label} in {example.name} promised {promised} and pointed "
            f"a {page.evaluate(AIM_CURSOR)} cursor at it"
        )
        page.mouse.click(*point)
        page.keyboard.up("Alt")
        composer = page.locator(".lf-composer")
        if promised is None:
            # Nothing outlined is nothing to aim at — no item encloses this point — and an
            # armed press then acts on nothing rather than falling back to the page. A
            # suggestion's ✓ Accept is where that matters: its row hangs in the page's own
            # column, outside the element it decides, so nothing is above it to aim at and
            # a press let through would send Claude a decision.
            expect(composer).to_be_hidden()
        else:
            expect(composer).to_be_visible()
            assert page.evaluate(DRAFT_MARK) == promised, (
                f"⌥-clicking {label} in {example.name} promised {promised} and commented "
                f"on {page.evaluate(DRAFT_MARK)}"
            )
            # And the promise is kept where the reader can see it kept. An outline needs
            # a box, and an item that draws none — every suggestion is display: contents —
            # would take the mark to 0x0 at the document's origin, showing nothing. The
            # composer places itself off this same record, so it would go to the top of
            # the window along with it, beside a passage it is no longer beside.
            unshown = page.evaluate(
                """() => [...document.querySelectorAll('.lf-mark-el.lf-pending')]
                   .filter(e => { const b = e.getBoundingClientRect();
                                  return !(b.width && b.height); })
                   .map(e => e.tagName.toLowerCase())"""
            )
            assert not unshown, (
                f"⌥-clicking {label} in {example.name} outlined {unshown}, which draws "
                "no box, so the promise is invisible and the composer stands off a rect "
                "at the top of the document"
            )
            # Put the composer away before reading the page back: its own passage wears
            # the outline, which is the one mark an aim is supposed to leave.
            page.keyboard.press("Escape")
            expect(composer).to_be_hidden()
            aimed += 1
        assert page.evaluate(PAGE_MARKUP) == before, (
            f"⌥-clicking {label} in {example.name} changed the page, so a press the aim "
            "had taken reached a widget as well"
        )
        assert not page.evaluate(FOCUS_IN_PAGE), (
            f"⌥-clicking {label} in {example.name} left the focus on the page, so the "
            "press reached the control under it"
        )
        pressed += 1
    assert pressed, f"{example.name} pressed nothing, so it asserts nothing"
    # And that the outline is still painted at all: a preview that stopped appearing would
    # leave every press above asserting only that nothing happened, which is the shape of
    # vacuous pass this sweep is most exposed to.
    assert aimed, f"{example.name} outlined nothing, so no press was held to a promise"
    # The other half of "did nothing else", and the half the markup cannot show: a widget
    # that acts tells Claude so, and a decision the user never made is worse in the log
    # than on the page. The wait is the page's own sends coming back, so a stray one is in
    # the log to be read rather than still in flight.
    round_trip(page)
    assert [
        e for e in interact.read_events(serve.page_dir) if e["kind"] == "action"
    ] == []
    assert errors == []
    page.close()


def test_a_key_still_reaches_its_control_after_an_aimed_press(browser, serve):
    """The aim holds its claim until the next press starts, and a key is not one.

    `offer` supplies the keys a span doesn't come with by calling click(), so a control
    worked from the keyboard sends a click with no press behind it. Taken for the aim's
    own, it goes nowhere at all: the user presses Enter on a pick mark and nothing is
    picked, on a page where the last thing they did with the mouse was aim."""
    page, errors = open_page(browser, serve(REPLAYED_PAGE))
    heading = page.locator("#t")
    heading.hover()
    page.keyboard.down("Alt")
    heading.click()
    page.keyboard.up("Alt")
    composer = page.locator(".lf-composer")
    expect(composer).to_be_visible()  # the press was the aim's, so its claim now stands
    page.keyboard.press("Escape")
    expect(composer).to_be_hidden()

    page.locator("#opt-shim .lf-pick").focus()
    page.keyboard.press("Enter")
    expect(page.locator("#approach > lf-option[chosen]")).to_have_count(1)
    round_trip(page)
    assert [
        e["action"] for e in interact.read_events(serve.page_dir) if "action" in e
    ] == ["choose"]
    assert errors == []
    page.close()


def test_the_aim_still_promises_while_a_composer_is_open(browser, serve):
    """An armed press with the box up re-anchors it, so the aim must still say where.

    claimPress acts whether or not a composer stands open, and openComposer carries the
    typed text onto the new anchor — so the aim standing down on composerOpen, as it did
    from its first commit, left exactly one press made blind: the one that moves a
    draft. Holding ⌥ over a second item raises its box beside the draft's own mark;
    two at once is the true state — where the draft stands, and where a press would
    move it — and the press then does what the box promised."""
    page, errors = open_page(browser, serve(REPLAYED_PAGE))
    heading = page.locator("#t")
    heading.hover()
    page.keyboard.down("Alt")
    heading.click()
    page.keyboard.up("Alt")
    composer = page.locator(".lf-composer")
    expect(composer).to_be_visible()
    composer.locator("textarea").fill("carried words")

    card = page.locator("#card-notes")
    card.hover()
    page.keyboard.down("Alt")
    promised = [page.evaluate(AIMED), page.evaluate(DRAFT_MARK)]
    assert promised == ["card-notes", "t"], (
        f"holding ⌥ over a card with a draft open on the heading showed {promised} as "
        "[aim, draft], so the press that would move the draft is blind"
    )
    card.click()
    page.keyboard.up("Alt")
    expect(composer).to_be_visible()
    expect(composer.locator("textarea")).to_have_value("carried words")
    assert [page.evaluate(AIMED), page.evaluate(DRAFT_MARK)] == [
        None,
        "card-notes",
    ], "the press re-anchored the draft, so its new anchor alone should stand marked"
    round_trip(page)
    assert [
        e for e in interact.read_events(serve.page_dir) if e["kind"] == "action"
    ] == []
    assert errors == []
    page.close()


def test_a_reload_under_a_held_aim_rearms_on_the_first_move(browser, serve):
    """The arm survives what the keydown cannot.

    `aiming` is armed by an Alt keydown, and a page reloaded under a held key — the
    poll following a new version does exactly this — never hears one, while claimPress
    reads live modifier state: every press on the new page was claimed and none could
    be promised. Mouse events carry that same live state, so the first move re-derives
    the arm; this drives that move rather than a keydown the reload already ate."""
    page, errors = open_page(browser, serve(REPLAYED_PAGE))
    heading = page.locator("#t")
    heading.hover()
    page.keyboard.down("Alt")
    expect(page.locator(".lf-aim")).to_have_attribute("data-for", "t")
    page.reload()
    page.wait_for_function(BOTH_STAMPS)
    expect(page.locator(".lf-aim[data-for]")).to_have_count(0)  # the latch is gone
    heading.hover()  # the first move under the still-held key
    expect(page.locator(".lf-aim")).to_have_attribute("data-for", "t")
    page.keyboard.up("Alt")
    assert errors == []
    page.close()


def test_an_open_tab_reloads_before_posting_through_a_revendored_layer(browser, serve):
    """The layer epoch closes the gap between a stopped server and an open tab.

    Polls are refused so the stale click, not a preceding state read, discovers the
    change. Its old contract must append nothing and reload; the same real click then
    succeeds under the replacement contract.
    """
    url = serve(REPLAYED_PAGE)
    page, errors = open_page(browser, url)
    old_layer = page_registry(page)["$layer"]["generation"]
    page.route("**/api/state*", refuse)
    page.wait_for_event(
        "request", predicate=lambda request: "/api/state" in request.url
    )

    old_server = serve.httpd
    address = old_server.server_address
    old_server.shutdown()
    old_server.server_close()
    project = serve.page_dir.parent / ".leaf"
    project.mkdir()
    (project / "theme.css").write_text(":root { --accent: rebeccapurple; }\n")
    initialized = CliRunner().invoke(
        interact.cli, ["page", "init", str(serve.page_dir)]
    )
    assert initialized.exit_code == 0, initialized.output
    new_layer = interact.layer_generation(serve.page_dir)
    assert new_layer != old_layer
    replacement = interact.LeafHTTPServer(
        address, interact.handler_for(serve.page_dir, TOKEN)
    )
    threading.Thread(target=replacement.serve_forever, daemon=True).start()
    serve.servers.append(replacement)
    serve.httpd = replacement

    with page.expect_navigation(wait_until="load"):
        page.locator("#opt-stage").click()
    page.wait_for_function("() => document.body.dataset.lfUpgraded === '1'")
    assert [
        event
        for event in interact.read_events(serve.page_dir)
        if event["kind"] == "action"
    ] == []

    page.unroute("**/api/state*")
    told(page)
    page.wait_for_function(BOTH_STAMPS)
    page.locator("#opt-stage").click()
    round_trip(page)
    actions = [
        event
        for event in interact.read_events(serve.page_dir)
        if event["kind"] == "action"
    ]
    assert [(event["widget"], event["action"]) for event in actions] == [
        ("approach", "choose")
    ]
    assert errors == []
    page.close()


def test_a_stale_custom_widget_uses_recursive_parent_eligibility(
    browser, serve, one_reader, tmp_path, monkeypatch
):
    """A project widget gets honest controls and authoritative stale rejection.

    A fresh tab projects a nested stopped plan and disables Increase. A deliberately
    stale tab still offers it, so its real press reaches POST; the same registry
    prerequisite must reject it there. The same absolute `set` action still admits a
    decrease while the parent is blocked.
    """
    monkeypatch.chdir(tmp_path)
    overlay = tmp_path / ".leaf"
    (overlay / "widgets").mkdir(parents=True)
    task = json.loads((interact.BUNDLED / "registry.json").read_text())["lf-task"]
    task["x-awaits"]["rollup"] = True
    (overlay / "registry.json").write_text(
        json.dumps(
            {
                "lf-task": task,
                "lf-quota": {
                    "description": "A project-defined absolute scalar control.",
                    "type": "object",
                    "properties": {
                        "id": {"type": "string"},
                        "slots": {"type": "string", "pattern": "^[0-9]+$"},
                        "restated": {"type": "boolean"},
                    },
                    "required": ["id", "slots"],
                    "additionalProperties": False,
                    "x-parent": ["lf-task"],
                    "x-content": "none",
                    "x-upgrade": True,
                    "x-state": {
                        "move": {
                            "detail": {
                                "type": "object",
                                "properties": {
                                    "to": {"type": "string"},
                                    "index": {"type": "integer", "minimum": 0},
                                },
                                "required": ["to", "index"],
                                "additionalProperties": False,
                            },
                            "facet": "placement",
                            "unit": "widget",
                            "record": {
                                "kind": "position",
                                "within": "lf-task",
                                "value": "to",
                                "order": "index",
                            },
                        },
                        "set": {
                            "detail": {
                                "type": "object",
                                "properties": {
                                    "slots": {
                                        "type": "string",
                                        "pattern": "^[0-9]+$",
                                    }
                                },
                                "required": ["slots"],
                                "additionalProperties": False,
                            },
                            "facet": "capacity",
                            "unit": "widget",
                            "record": {
                                "kind": "value",
                                "attr": "slots",
                                "value": "slots",
                            },
                            "requires": {
                                "target": "parent",
                                "awaiting": False,
                                "change": "increase",
                            },
                        },
                    },
                    "x-example": (
                        '<lf-tasks id="quota-example-tasks">'
                        '<lf-task id="quota-example-task" status="active">'
                        "<strong>Task</strong>"
                        '<lf-quota id="quota-example" slots="1"></lf-quota>'
                        '<lf-task id="quota-example-child" status="active">'
                        "<strong>Child</strong></lf-task>"
                        "</lf-task></lf-tasks>"
                    ),
                },
            }
        )
    )
    (overlay / "widgets" / "lf-quota.js").write_text(
        """\
import { actionAvailable, offer, once, sendAction } from "/leaf.js";

const detail = (quota, delta) => ({
  slots: String(Number(quota.getAttribute("slots")) + delta),
});

const paint = quota => {
  for (const [name, delta] of [["decrease", -1], ["increase", 1]])
    quota.querySelector(`[data-lf-quota="${name}"]`)?.setAttribute(
      "aria-disabled",
      String(!actionAvailable(quota, "set", detail(quota, delta))),
    );
};

async function change(quota, delta) {
  const next = detail(quota, delta);
  if (!actionAvailable(quota, "set", next)) return;
  const previous = quota.getAttribute("slots");
  quota.setAttribute("slots", next.slots);
  paint(quota);
  if (!await sendAction(quota, "set", next)) quota.setAttribute("slots", previous);
  paint(quota);
}

customElements.define("lf-quota", class extends HTMLElement {
  connectedCallback() {
    if (!once(this)) return;
    const decrease = offer("button", "lf-btn", "Decrease");
    decrease.dataset.lfQuota = "decrease";
    decrease.addEventListener("click", () => void change(this, -1));
    const increase = offer("button", "lf-btn", "Increase");
    increase.dataset.lfQuota = "increase";
    increase.addEventListener("click", () => void change(this, 1));
    this.append(decrease, increase);
    document.addEventListener("lf-actions", () => paint(this));
    paint(this);
    document.getElementById("destination")?.append(this);
  }
  applyAction(action, detail) {
    if (action === "move") document.getElementById(detail.to)?.append(this);
    else if (action === "set") this.setAttribute("slots", detail.slots);
    paint(this);
  }
});
"""
    )
    quota_v1 = leaf_page(
        "quota",
        '<h1 id="heading">Quota</h1><lf-tasks id="tasks">'
        '<lf-task id="task" status="active"><strong>Task</strong>'
        '<lf-quota id="quota" slots="1"></lf-quota>'
        '<lf-options id="quota-intervention" choose label="Proceed?">'
        '<lf-option id="quota-ready" chosen>Ready</lf-option></lf-options>'
        '<lf-task id="child" status="active"><strong>Child</strong></lf-task>'
        "</lf-task>"
        '<lf-task id="destination" status="active">'
        "<strong>Destination</strong></lf-task>"
        "</lf-tasks>",
    )
    url = serve(quota_v1)
    stale, stale_errors = open_page(browser, url, context=held_stale(one_reader))
    current, current_errors = open_page(browser, live_url(url), context=one_reader)

    interact.append_event(
        serve.page_dir,
        {
            "kind": "report",
            "author": "agent",
            "version": 1,
            "widget": "task",
            "action": "status",
            "detail": {"status": "blocked"},
        },
    )
    told(current)
    expect(current.locator("#task")).to_have_attribute("status", "blocked")
    # The answered direct intervention takes precedence over the nested task, so
    # changing the child alone does not close capacity.
    expect(current.get_by_role("button", name="Increase")).to_have_attribute(
        "aria-disabled", "false"
    )
    interact.append_event(
        serve.page_dir,
        {
            "kind": "report",
            "author": "agent",
            "version": 1,
            "widget": "child",
            "action": "status",
            "detail": {"status": "blocked"},
        },
    )
    told(current)
    expect(current.locator("#child")).to_have_attribute("status", "blocked")
    expect(current.get_by_role("button", name="Increase")).to_have_attribute(
        "aria-disabled", "false"
    )
    current.locator("#quota-ready").click()
    round_trip(current)
    expect(current.locator("#quota-ready")).not_to_have_attribute("chosen", "")
    expect(current.get_by_role("button", name="Increase")).to_have_attribute(
        "aria-disabled", "true"
    )
    expect(current.get_by_role("button", name="Decrease")).to_have_attribute(
        "aria-disabled", "false"
    )

    # A live activation imports fresh element identities. The module reparents quota
    # while upgrading, but eligibility still reads v2's pristine authored parent.
    quota_v2 = (
        quota_v1.replace(
            '<lf-task id="task" status="active">',
            '<lf-task id="task" status="blocked">',
        )
        .replace(
            '<lf-task id="child" status="active">',
            '<lf-task id="child" status="blocked">',
        )
        .replace('id="quota-ready" chosen', 'id="quota-ready"')
    )
    (serve.page_dir / "versions" / "v2.html").write_text(quota_v2)
    interact.append_event(
        serve.page_dir,
        {"kind": "note", "author": "claude", "version": 2, "text": "same plan"},
    )
    told(current)
    expect(current.locator(".lf-version")).to_contain_text("v2")
    expect(current.locator("#destination > #quota")).to_have_count(1)
    expect(current.get_by_role("button", name="Increase")).to_have_attribute(
        "aria-disabled", "true"
    )

    expect(stale.locator("#task")).to_have_attribute("status", "active")
    expect(stale.get_by_role("button", name="Increase")).to_have_attribute(
        "aria-disabled", "false"
    )
    stale.get_by_role("button", name="Increase").click()
    round_trip(stale)

    assert [event["action"] for event in actions(serve.page_dir)] == ["choose"]
    stale.unroute("**/api/state*")
    told(stale)
    expect(stale.locator("#quota")).to_have_attribute("slots", "1")
    expect(stale.get_by_role("button", name="Increase")).to_have_attribute(
        "aria-disabled", "true"
    )

    interact.append_event(
        serve.page_dir,
        {
            "kind": "action",
            "author": "user",
            "version": 1,
            "widget": "quota",
            "action": "move",
            "detail": {"to": "destination", "index": 0},
        },
    )
    told(current)
    expect(current.locator("#destination > #quota")).to_have_count(1)
    expect(current.get_by_role("button", name="Increase")).to_have_attribute(
        "aria-disabled", "false"
    )

    current.get_by_role("button", name="Decrease").click()
    round_trip(current)
    expect(current.locator("#quota")).to_have_attribute("slots", "0")
    assert [event["action"] for event in actions(serve.page_dir)] == [
        "choose",
        "move",
        "set",
    ]
    assert current_errors == []
    assert stale_errors and all("400" in error for error in stale_errors)
    stale.close()
    current.close()


def test_a_self_eligibility_check_reads_state_before_its_optimistic_gesture(
    browser, serve, tmp_path, monkeypatch
):
    """The common send door must not mistake a gesture's paint for prior state."""
    monkeypatch.chdir(tmp_path)
    overlay = tmp_path / ".leaf"
    overlay.mkdir()
    bundled = json.loads((interact.BUNDLED / "registry.json").read_text())
    options = bundled["lf-options"]
    options["x-state"]["choose"]["requires"] = {
        "target": "self",
        "awaiting": True,
    }
    (overlay / "registry.json").write_text(json.dumps({"lf-options": options}))
    url = serve(
        leaf_page(
            "self eligibility",
            '<h1 id="heading">Choose</h1><lf-options id="pick" choose>'
            '<lf-option id="pick-a">A</lf-option>'
            '<lf-option id="pick-b">B</lf-option></lf-options>',
        )
    )
    page, errors = open_page(browser, url)

    page.get_by_role("button", name=re.compile(r"^choose one: A")).click()
    round_trip(page)

    expect(page.locator("#pick-a")).to_have_attribute("chosen", "")
    assert [event["action"] for event in actions(serve.page_dir)] == ["choose"]
    assert errors == []
    page.close()


def test_a_runtime_cannot_adopt_a_new_registry_while_it_is_loading(browser, serve):
    """The runtime bytes and registry are one contract, even across a slow fetch."""
    url = serve(REPLAYED_PAGE)
    gate_registry_once = """
      if (!sessionStorage.getItem('lf-gated-registry')) {
        sessionStorage.setItem('lf-gated-registry', '1');
        const nativeFetch = window.fetch.bind(window);
        window.lfRegistryGate = new Promise(
          resolve => window.lfReleaseRegistry = resolve
        );
        window.fetch = (...args) => {
          const input = args[0];
          const requested = typeof input === 'string' ? input : input.url;
          if (new URL(requested, location.href).pathname === '/registry.json') {
            window.lfRegistryBlocked = true;
            return window.lfRegistryGate.then(() => nativeFetch(...args));
          }
          return nativeFetch(...args);
        };
      }
    """
    page, errors = open_page(
        browser,
        url,
        init_script=gate_registry_once,
        wait_until="domcontentloaded",
        upgraded=False,
    )
    page.wait_for_function("() => window.lfRegistryBlocked === true")
    old_layer = interact.layer_generation(serve.page_dir)

    old_server = serve.httpd
    address = old_server.server_address
    old_server.shutdown()
    old_server.server_close()
    initialized = CliRunner().invoke(
        interact.cli, ["page", "init", str(serve.page_dir)]
    )
    assert initialized.exit_code == 0, initialized.output
    assert interact.layer_generation(serve.page_dir) != old_layer
    replacement = interact.LeafHTTPServer(
        address, interact.handler_for(serve.page_dir, TOKEN)
    )
    threading.Thread(target=replacement.serve_forever, daemon=True).start()
    serve.servers.append(replacement)
    serve.httpd = replacement

    with page.expect_navigation(wait_until="load"):
        page.evaluate("() => window.lfReleaseRegistry()")
    page.wait_for_function(BOTH_STAMPS)
    assert page.evaluate("() => sessionStorage.getItem('lf-gated-registry')") == "1"
    assert errors == []
    page.close()


def test_design_mode_comments_on_what_a_press_lands_on_and_nothing_else(browser, serve):
    """A press in design mode is a comment about the layer, and that is all it does.

    The mode is the ⌥ aim generalized: a press on a widget names the widget rather than
    working it, so a pick mark can be pointed at without picking. The comment posts
    with `about: "layer"`, which is how the agent tells "this control looks wrong" from
    a remark about the words — nothing about the anchor alone says which. Both halves
    are asserted: the log's event, and the page exactly as it was."""
    page, errors = open_page(browser, serve(REPLAYED_PAGE))
    option = page.locator("#opt-shim")
    before = page.evaluate(PAGE_MARKUP)
    page.keyboard.press("i")
    expect(page.locator("body")).to_have_class(re.compile(r"\blf-design\b"))
    # The mode shows what is on the page rather than waiting for the pointer: a legend
    # box on every item, and on every item but a widget's parts its name — the group
    # is named, its options wear the hairline alone and are named under the pointer.
    box_of = lambda id: page.locator(f'.lf-legend-box[data-for="{id}"]')
    expect(box_of("t")).to_be_visible()
    assert set(
        page.eval_on_selector_all(".lf-legend-box", "bs => bs.map(b => b.dataset.for)")
    ) == set(page.eval_on_selector_all("main [id]", "es => es.map(e => e.id)"))
    expect(box_of("approach").locator(".lf-legend-tag")).to_have_text(
        "lf-options · approach"
    )
    expect(box_of("t").locator(".lf-legend-tag")).to_have_text("heading · t")
    expect(box_of("opt-shim").locator(".lf-legend-tag")).to_have_count(0)
    page.wait_for_function(LEGEND_TRUE)
    # Hovering names the target — the tag and the id a fix is written against — and
    # draws the aim's own box on it, the promise about the next press.
    option.hover()
    expect(page.locator(".lf-inspect")).to_have_text("lf-option · opt-shim")
    expect(page.locator(".lf-aim")).to_have_attribute("data-for", "opt-shim")
    option.click()
    composer = page.locator(".lf-composer")
    expect(composer).to_be_visible()
    expect(page.locator("#lf-composer-quote")).to_have_text(
        "layer · lf-option · opt-shim"
    )
    # The press did nothing to the page: not a pick, not a focus, nothing in the markup
    # but the composer's own outline on the element it is about.
    expect(page.locator("#approach > lf-option[chosen]")).to_have_count(0)
    assert (
        page.evaluate(PAGE_MARKUP).replace(' class="lf-mark-el lf-pending"', "")
        == before
    )
    assert not page.evaluate(FOCUS_IN_PAGE)
    page.locator(".lf-composer textarea").fill("the ring reads too heavy")
    page.keyboard.press("ControlOrMeta+Enter")
    round_trip(page)
    events = interact.read_events(serve.page_dir)
    posted = [e for e in events if e["kind"] == "comment"]
    assert [(e["about"], e["anchor"]) for e in posted] == [
        ("layer", {"section": "opt-shim"})
    ]
    assert [e for e in events if e["kind"] == "action"] == []
    # The panel names the thread the same way the composer named the box, and the send
    # lands typing in that thread's reply box.
    expect(page.locator(".lf-thread .lf-quote")).to_have_text(
        "layer · lf-option · opt-shim"
    )
    expect(page.locator(".lf-thread textarea")).to_be_focused()
    # Escape backs out one rung at a time — the box, then the mode.
    page.keyboard.press("Escape")
    expect(page.locator(".lf-thread")).to_be_focused()
    expect(page.locator("body")).to_have_class(re.compile(r"\blf-design\b"))
    page.keyboard.press("Escape")
    expect(page.locator("body")).not_to_have_class(re.compile(r"\blf-design\b"))
    expect(page.locator(".lf-inspect")).to_be_hidden()
    expect(page.locator(".lf-legend-box")).to_have_count(0)
    assert errors == []
    page.close()


def test_design_mode_reaches_the_chrome_and_names_the_control(browser, serve):
    """The banner, the panel, a control on either: what no comment could reach before.

    The anchor pass passes over the runtime's own layer, so a remark about the Comments
    button had nowhere to land. In design mode the press on it is a comment on it —
    anchored on the part the runtime named (`lf-banner`), naming the control the press
    landed on — and the button does not do what it does: the panel stays closed."""
    page, errors = open_page(browser, serve(REPLAYED_PAGE))
    page.keyboard.press("i")
    comments = page.locator(".lf-banner .lf-comments")
    said = comments.inner_text()  # "Comments (0)" — the control's word is what it shows
    comments.hover()
    expect(page.locator(".lf-inspect")).to_have_text(f"{said} · banner")
    comments.click()
    expect(page.locator(".lf-composer")).to_be_visible()
    expect(page.locator("#lf-composer-quote")).to_have_text(f"layer · {said} · banner")
    expect(page.locator(".lf-panel")).to_be_hidden()
    page.locator(".lf-composer textarea").fill("reads dim against the wash")
    page.keyboard.press("ControlOrMeta+Enter")
    round_trip(page)
    posted = [e for e in interact.read_events(serve.page_dir) if e["kind"] == "comment"]
    assert [(e["about"], e["anchor"]) for e in posted] == [
        ("layer", {"section": "lf-banner", "part": said})
    ]
    # The thread's mark is the outline an element anchor wears, on the chrome too.
    expect(page.locator("#lf-banner")).to_have_class(re.compile(r"\blf-mark-el\b"))
    page.keyboard.press("Escape")

    # And the comment panel, which is the case where the aim's own geometry had nothing to
    # say. A fixed box is not clipped by the page's scroller, and body is that scroller
    # narrowed to the column standing beside the panel — so the panel measured through its
    # ancestors came back wholly clipped away, and a mode whose row promises a click on the
    # chrome drew nothing over the chrome. Wide enough for the panel to stand beside the
    # page, which is where body and the panel part company.
    resized(page, 1280, 800)
    page.locator(".lf-banner .lf-comments").click()
    expect(page.locator(".lf-panel")).to_be_visible()
    page.wait_for_function(
        "() => document.querySelector('.lf-panel').getBoundingClientRect().left"
        " >= document.body.clientWidth"
    )
    page.keyboard.press("i")
    box = page.locator(".lf-panel").bounding_box()
    page.mouse.move(box["x"] + box["width"] / 2, box["y"] + 30)
    expect(page.locator(".lf-aim")).to_have_attribute("data-for", "lf-comments")
    assert page.evaluate(
        """() => {
             const aim = document.querySelector('.lf-aim').getBoundingClientRect();
             const panel = document.querySelector('.lf-panel').getBoundingClientRect();
             return Math.abs(aim.width - panel.width) < 3
                 && Math.abs(aim.left - panel.left) < 3;
           }"""
    ), "the aim's box does not stand on the panel it names"
    assert errors == []
    page.close()


def test_design_mode_takes_an_edge_rather_than_drawing_it(browser, serve):
    """The mode promises that a press comments on what it lands on and does nothing else,
    and a region's edge is the piece of chrome whose press moves the page rather than the
    page's content. A drag on it under the mode leaves the region where it was and opens a
    composer naming the edge, which is what a reader remarking on it has to be able to do.

    Neither half is anything the edge knows: the mode takes the press above the runtime's
    own handler, and the name comes of the platform's word for what the press landed on.
    So this is a reading of whether a new control joins the mode by being one — which is
    what it would stop doing the day an edge answered a press for itself. One edge is the
    whole reading, both being one handler (`drawnEdge`); what the second edge could break
    here it would break for the first too."""
    edge = EDGES[0]
    page, errors = open_page(browser, serve(LONG_PAGE, comments=1))
    resized(page, 1280, 800)
    page.locator(".lf-comments").click()
    panel_settled(page)
    standing = geometry(page, edge)
    page.keyboard.press("i")
    draw_edge(page, edge, 160)
    held = geometry(page, edge)
    expect(page.locator(".lf-composer")).to_be_visible()
    expect(page.locator("#lf-composer-quote")).to_have_text(
        "layer · Comment panel width · comments"
    )
    page.close()

    assert held["width"] == standing["width"], (
        f"the mode moved the edge it was asked to comment on: {standing} then {held}"
    )
    assert held["chosen"] is None, (
        f"a press the mode took was still recorded as the reader's width: {held}"
    )
    assert errors == []


def test_design_mode_leaves_prose_to_the_selection(browser, serve):
    """Words are still the way to point at words: a drag on prose selects, and the
    comment it raises is about the layer; a plain click on prose comments on the block.

    The mode takes presses on widgets, controls and the chrome at the press, ahead of the
    page. Prose it leaves to the browser, or "this heading is too small" would have no
    way to quote the heading."""
    page, errors = open_page(browser, serve(REPLAYED_PAGE))
    page.keyboard.press("i")
    heading = page.locator("#t")
    box = heading.bounding_box()
    select(
        page,
        (box["x"] + 2, box["y"] + box["height"] / 2),
        (box["x"] + box["width"] - 2, box["y"] + box["height"] / 2),
    )
    fab = page.locator(".lf-fab")
    expect(fab).to_be_visible()
    fab.click()
    expect(page.locator(".lf-composer")).to_be_visible()
    expect(page.locator("#lf-composer-quote")).to_have_text(
        "layer · heading · t · “Rollout”"
    )
    page.keyboard.press("Escape")  # the composer, draft kept; the mode still stands
    expect(page.locator(".lf-composer")).to_be_hidden()
    expect(page.locator("body")).to_have_class(re.compile(r"\blf-design\b"))
    heading.click(position={"x": 4, "y": 4})
    expect(page.locator(".lf-composer")).to_be_visible()
    expect(page.locator("#lf-composer-quote")).to_have_text("layer · heading · t")
    assert errors == []
    page.close()


def test_design_mode_survives_the_reload_a_new_version_brings(browser, serve):
    """A version landing mid-batch reloads the document, and a reader put out of the
    mode by news they never asked for is a mode error the page made — so the mode is
    this tab's working state, kept the way the panel's open state is."""
    page, errors = open_page(browser, serve(REPLAYED_PAGE))
    page.keyboard.press("i")
    expect(page.locator("body")).to_have_class(re.compile(r"\blf-design\b"))
    page.reload()
    page.wait_for_function(BOTH_STAMPS)
    expect(page.locator("body")).to_have_class(re.compile(r"\blf-design\b"))
    expect(page.locator('.lf-legend-box[data-for="approach"]')).to_be_visible()
    page.keyboard.press("Escape")
    expect(page.locator("body")).not_to_have_class(re.compile(r"\blf-design\b"))
    page.reload()
    page.wait_for_function(BOTH_STAMPS)
    expect(page.locator("body")).not_to_have_class(re.compile(r"\blf-design\b"))
    assert errors == []
    page.close()


# Every legend box stands on its item: same corner, one pixel out, for every item wholly
# on screen. Items partly off it are clipped to the scroller (shownRect) and are not
# compared, and items off it have no box shown at all. An item with no box of its own —
# one a page styles display: contents — reads as what its contents paint, mirroring
# shownRect's fallback: its host rect is 0×0 at the origin, which would otherwise count
# as "wholly on screen" and fail every off-screen one for its rightly hidden box.
LEGEND_TRUE = """() => [...document.querySelectorAll('.lf-legend-box')].every(b => {
  const it = document.getElementById(b.dataset.for);
  let r = it.getBoundingClientRect();
  if (!r.width && !r.height) {
    const contents = document.createRange();
    contents.selectNodeContents(it);
    r = contents.getBoundingClientRect();
  }
  if (r.top < 0 || r.bottom > innerHeight) return true;
  if (b.style.display === 'none') return false;
  const bb = b.getBoundingClientRect();
  return Math.abs(bb.left + 1 - r.left) < 1.5 && Math.abs(bb.top + 1 - r.top) < 1.5
    && Math.abs(bb.width - 2 - r.width) < 1.5 && Math.abs(bb.height - 2 - r.height) < 1.5;
})"""


def test_the_legend_follows_the_page_it_is_a_reading_of(browser, serve):
    """A legend box kept from a previous reading is a claim about a page that has moved.

    Three of the doors that move it: the page scrolling (items come on screen with no
    box yet, and the boxes are drawn in document space), the panel opening (the column
    re-centres, every block reflows, and no scroll or replay says so — each item's own
    resize does), and the name under the pointer, which is drawn beside the box in the
    same space: it sat in viewport space once, with the scroll added on top, and stood a
    screen below its box on any page scrolled at all. The aim is one more of the
    chrome's promises over the same page, so the reflow doors repaint it too
    (pageShifted): it once kept its old coordinates through the panel's slide, a box
    and name floating half a panel to the right of the element they claimed."""
    page, errors = open_page(browser, serve(LONG_PAGE))
    page.keyboard.press("i")
    page.wait_for_function(LEGEND_TRUE)
    page.locator("body").evaluate("b => { b.scrollTop = 1200; }")
    p = page.locator("#p20")
    expect(p).to_be_in_viewport()
    expect(page.locator('.lf-legend-box[data-for="p20"]')).to_be_visible()
    page.wait_for_function(LEGEND_TRUE)
    # The name floats where the box's tag stood, over the item's corner — on a scrolled
    # page as on a fresh one.
    p.hover()
    expect(page.locator(".lf-inspect")).to_have_text("paragraph · p20")
    box = page.locator(".lf-aim").bounding_box()
    name = page.locator(".lf-inspect").bounding_box()
    assert abs(name["y"] + name["height"] - box["y"]) < 4, (name, box)
    assert abs(name["x"] - box["x"]) < 4, (name, box)
    # The panel takes a strip from the page and every block moves; the legend moves
    # with them, off the resize each item reports. Opened by key: in the mode a press
    # on the Comments button is a comment about the button.
    page.keyboard.press("c")
    expect(page.locator(".lf-panel")).to_be_visible()
    page.wait_for_function(
        "() => document.body.getAnimations().every(a => a.playState !== 'running')"
    )
    page.wait_for_function(LEGEND_TRUE)
    # The legend's repaint above consumed the reflow's edge, and the aim was refreshed
    # in the same pageShifted, so one plain read is the settled answer: the pointer
    # still rests in p20, and the promise is about where p20 stands now.
    aim = page.evaluate(
        """() => {
      const b = document.querySelector('.lf-aim');
      const it = document.getElementById(b.dataset.for);
      const r = it.getBoundingClientRect();
      const bb = b.getBoundingClientRect();
      return { on: b.dataset.for, dx: bb.left - r.left, dy: bb.top - r.top };
    }"""
    )
    assert aim["on"] == "p20" and abs(aim["dx"]) < 2 and abs(aim["dy"]) < 2, aim
    assert errors == []
    page.close()


